const translations={fr:{home:"Accueil.",about:"À propos.",skills:"Compétences.",portfolio:"Portfolio.",contact:"Contact.",yo:"Salut !",presentation:"Je m'appelle Danih Stephane",engineer:"Ingénieur",developer:"Développeur",coder:"Codeur",get_in_touch:"Entrer en contact",years_of_experience:"Années d'expérience",completed_projects:"Projets terminés",happy_clients:"Clients satisfaits",about_me:"à propos de moi",title_introduction:"Solution d'application innovante ? Réalisons vos idées !",introduction:"Salut 👨‍💻, je suis Danih Stéphane Rakotoarison Harilanto, développeur sénior. Passionné par les technologies de l'information, j'ai travaillé sur divers projets, notamment des solutions SaaS et des services cloud. Mon expertise couvre le développement full stack et la collaboration avec des équipes créatives, visant à transformer des idées en solutions concrètes. Que ce soit en solo ou en équipe, je mise sur une gestion efficace des projets, l'agilité et une communication ouverte pour assurer le succès.",hire_me:"Embauchez-moi",download_cv:"Telecharger CV",my_skills:"Mes compétences",title_skills:"Quels sont les éventails de mes compétences techniques en développement ?",skills_desc:"Voici les aptitudes techniques et les outils de développement qui me permettent de transformer des concepts en applications web fonctionnelles et intuitives, alliant maîtrise des langages de programmation, frameworks modernes et environnements de développement optimisés",skills_button:"Compétences",tools_button:"Applications",my_experiences:"Professionnelles",experience_title:"Plus de 5 ans d'expérience en entreprise avec une forte implication dans des projets personnels",experience_introduction:"J’ai eu l’opportunité de travailler sur divers projets, principalement dans le domaine des solutions SaaS et des services cloud. Au cours de ces expériences, j'ai été impliqué dans plusieurs tâches et responsabilités, allant du développement de fonctionnalités spécifiques à l'optimisation de l'architecture des systèmes. Cette immersion m'a permis d'acquérir une solide compréhension des défis techniques et des meilleures pratiques associés à ces environnements dynamiques.",june_2023_present:"Juin 2023 - Présent 2024",first_box_title:"Gestion de données avec ETL",first_box_description:"Extraction : \n Intégration de données variées (CSV, SQL). \n Extraction planifiée et régulière des données. \nPrétraitement pour corriger et normaliser les formats. \n \n Transformation : \n Application de transformations complexes via des pipelines. \n Nettoyage et enrichissement des données. \n Création de nouvelles features à partir des données brutes. \n \n Chargement : \n Stockage des données dans un entrepôt central. \n Disponibilité des données pour analyse et visualisation.",techno:"Écosystème de développement",june_2022_june_2023:"Juin 2022 - Juin 2023",second_box_title:"Optimisation d'une SaaS",second_box_description:"Amélioration de l'application web de gestion des données afin d'améliorer l'efficacité et la précision de la collecte statistique. Ce projet vise à intégrer des fonctionnalités avancées pour faciliter la saisie, le traitement et l'analyse des données, tout en garantissant une interface utilisateur intuitive et conviviale.",specifications:"Spécifications",specifications_descriptions:"Gestion de projet pour la collecte : base de données, interface avec l'écosystème client, encaissement des chèques, ciblage marketing, et datavisualisation.",feb_2022_mai_2022:"Fébr. 2022 - mai 2022",third_box_title:"Révision d'une Interface de Saisie de Données",third_box_description:"Correction et amélioration d'un outil de saisie de données, intégrant des validations avancées, la possibilité d'importer des fichiers, l'exportation des données traitées, et la gestion des utilisateurs avec des droits d'accès.",technical:"Référentiels techniques",aug_2021_des_2021:"Août 2021 - Déc 2021",fourth_box_title:"Développeur Java",fourth_box_description:"Mobile Banking, application android native, améliore l'accessibilité et la commodité des services bancaires, permettant aux utilisateurs de gérer leurs finances à tout moment et de n'importe où.",characteristics:"Caractéristiques",nov_2024_jan_2025:"Nov. 2024 - Janv. 2025",seventh_box_title:"Développeur IA & Mentor",seventh_box_role:"Mentorat Technique & Intégration IA",seventh_box_description:"Développeur IA et Mentor Technique spécialisé en solutions React et Symfony. Encadrement d'équipes de développement, intégration de solutions IA locales (Ollama), architecture scalable avec Docker et Mercure pour le temps réel, et mise en place des meilleures pratiques de développement.",jan_2025_jun_2025:"Janv. 2025 - Juin 2025",sixth_box_title:"Refonte d'une Plateforme de Réservation de Véhicules",sixth_box_role:"Architecte Fullstack & Performance",sixth_box_description:"Refonte d'une plateforme de location de véhicules : interface Next.js/React ultra-réactive, backend Symfony sécurisé, filtrage intelligent, paiements mobile banking, dashboard back-office sur-mesure et optimisation SEO. Résultats : +40% réservations, -30% abandon, -50% temps de chargement.",nov_2025_present:"Nov. 2025 - Présent",eighth_box_title:"Agentic IA & Analyse Géospatiale",eighth_box_role:"Projet AGREETECH",eighth_box_description:"Développement d'une plateforme d'analyse géospatiale agentique dans le cadre du projet AGREETECH. Conception de modules permettant le dessin interactif de zones agricoles sur carte, l'analyse d'imagerie satellite via Google Earth Engine, les calculs géospatiaux avancés (surface, périmètre, centroïde) avec Turf.js, et la visualisation de données environnementales via Chart.js. Architecture React 19 + TypeScript, état applicatif Redux Toolkit, données serveur React Query, UI Material-UI et build Vite.",jul_2025_present:"Juil. 2025 - Présent",fifth_box_title:"Lead Technique & PMO — IA et Cartographie Temps Réel",fifth_box_role:"Lead Technique & PMO IA",fifth_box_description:"Élu Développeur Senior après un assessment interne exigeant. En tant que Lead Technique et PMO, pilotage de modules critiques intégrant cartographie temps réel et IA, conduite des code reviews, coordination du cycle projet complet et interface stratégique entre les équipes techniques et les directions métier.",my_education:"Mes antécédents",education_title:"Comment un voyage éducatif peut-il mener à l'excellence en technologie ?",education_description:"Au cours de mon parcours scolaire en développement informatique, j'ai eu l'opportunité d'obtenir une maîtrise dans l'une des meilleures universités d'Europe, où j'ai approfondi mes connaissances théoriques et pratiques. Cette expérience m'a permis de renforcer mes compétences en développement d'applications, tout en bénéficiant d'une solide formation en informatique dispensée par des universités locales. Parallèlement, j'ai acquis une base rigoureuse en mathématiques, essentielle pour la résolution de problèmes complexes et l'optimisation des algorithmes, me préparant ainsi à relever les défis techniques du secteur.",education_first_box_title:"Université Côte d'Azur",education_first_box_description:"Ingénierie informatique. Parcours Mobiquité, Big Data et intégration de Systèmes (MBDS)",license:"Licence",education_second_box_title:"IT Univesity",education_second_box_descirption:"Technologies de l''information. Spécialisé dans le développement d'applications ou la programmation.",academic:"Académique",education_third_box_title:"Faculté des sciences mathématiques",education_third_box_description:"L'analyse, l'algèbre, la géométrie, la théorie des probabilités et des statistiques, la logique, la démonstration, ainsi que le calcul vectoriel et matriciel.",intensive_courses:"Cours intensifs",languages:"Languages",malagasy:"Malgache (MG)",french:"Français (FR)",french_desc:"/ 2ème native",english:"Anglais (EN)",english_desc:"Compétence professionnelle",german:"Allemand (DE)",german_desc:"Débutant",my_works:"Mes travaux",my_works_title:"Des solutions innovantes qui défient les attentes : Mes Projets",my_works_introduction:"Conception de sites Web d'exception alliant fonctionnalité et esthétique, garantissant une utilité à long terme pour les utilisateurs. Élaboration d'une interface soigneusement conçue, claire et bien documentée, veillant à la fluidité et à l'intuitivité de chaque interaction. Objectif de création de solutions élégantes répondant aux besoins actuels des clients et les préparant pour l'avenir.",load_more_work:"Charger plus de travail",recommandation_title:"Curieux de savoir ce que mes collègues disent de moi ? Voici leurs avis !",recommandation_introduction:"Dans le cadre de ma recherche de nouvelles opportunités professionnelles, je souhaite partager avec vous les recommandations de mes collaborateurs et mentors. Leurs commentaires témoignent de mes compétences, de mon éthique de travail et de ma capacité à collaborer efficacement en équipe. Chaque témoignage reflète une expérience unique, mettant en lumière les qualités qui font de moi un candidat idéal pour un poste en tant que développeur.",recommandation_conclusion:"Vous pouvez ajouter des recommandations sur LinkedIn",contact_title:"Avez-vous une idée ou un projet ?  N'hésitez pas à me laisser un message !",contact_desc:"Pour toute assistance, n'hésitez pas à me contacter et à me faire savoir comment je peux vous aider. Remplissez le formulaire, et je vous répondrai dans les plus brefs délais.",address:"Adresse:",phone:"Téléphone:",phone_form:"Téléphone (Optionelle)",name:"Nom",ex_name:"ex. Jules Dupont",ex_email:"ex. jules.dupont@gmail.com",optional:"Numéro de téléphone",write_a_message:"Ecrire un message",send:"Envoyer",proundly:"Conçu avec passion, propulsé par l'innovation",recommandation_name1:"Diary Razafinjatovo · 1er",recommandation_post1:"Chef de projet / Certified Product Owner | Scrum master",recommandation_date1:"Mis en ligne le : 24 septembre 2024",recommandation_function1:"Diary était le/la manager direct(e) de Danih Stephane",recommandation_desc1:"J'ai eu le plaisir de travailler avec Danih en tant que son manager, et je peux affirmer que c'est un professionnel exceptionnel. Passionné et toujours à la recherche d'innovation, il a constamment apporté des solutions créatives à chaque projet auquel il a contribué. \n Il se distingue par son sérieux, son engagement et sa capacité à anticiper les besoins du projet tout en proposant des idées innovantes. Que ce soit pour résoudre des problèmes complexes ou pour optimiser les processus de développement, il a toujours su trouver des solutions efficaces. \n Sa passion pour le développement et son souci du détail font de lui un atout précieux pour toute équipe. \n Je le recommande vivement.",recommandation_name2:"ZAFIMANANGA Josio Rigonolde · 1er",recommandation_post2:"Développeur PHP (Symfony, WordPress, ...) / ReactJs",recommandation_date2:"Mis en ligne le : 23 septembre 2024",recommandation_function2:"ZAFIMANANGA travaillait avec Danih Stephane dans la même équipe",recommandation_desc2:"J'ai eu le plaisir de collaborer étroitement avec Danih qui a su démontrer une persévérance dans chaque mission qui lui a été confié. Même face à des défis et témoigne une grande détermination. \n Au sein de notre équipe chez eTech, il s'est rapidement adapté aux processus et aux outils de développement en place. Sa capacité à s'intégrer facilement dans un environnement en constante évolution est une qualité précieuse qui lui permet de contribuer efficacement aux projets collectifs. \n Danih a rapidement trouvé sa place au sein de notre équipe grâce à son excellent esprit d'équipe. Toujours prêt à collaborer et à partager ses idées, il a su apporter une énergie positive qui a renforcé la dynamique de groupe. \n Il s'intéresse constamment à l'amélioration de ses compétences, ce qui lui permet de progresser rapidement et de contribuer de manière significative à chaque projet.",recommandation_name3:"Njaratiana Herivola RAZAFINDRABE · 1er",recommandation_post3:"Teach lead (PHP/Symfony/Laravel) | Scrum master | Product Owner",recommandation_date3:"Mis en ligne le : 20 septembre 2024",recommandation_function3:"Njaratiana Herivola était le/la manager direct(e) de Danih Stephane",recommandation_desc3:"Danih, c'est un développeur passionné, très réactif et proactif à la fois. Il communique aussi bien avec l'équipe qu'avec nos clients. Il est aussi un bon mentor pour les stagiaires qui travaillaient dans l'équipe. La plupart du temps, il nous surprend avec des projets extra qui mettent en évidence sa passion pour l'IA. Je le recommende fortement. Il sera un bon lead développeur ;)",recommandation_name4:"Onintsoa Randriamiarinamanana · 1er",recommandation_post4:"IT DeveloperIT Developer",recommandation_date4:"Mis en ligne le : 19 septembre 2024",recommandation_function4:"Onintsoa travaillait avec Danih Stephane dans la même équipe",recommandation_desc4:"J'ai pu collaborer avec Danih sur plusieurs projets, et ses compétences en programmation sont remarquables. Son code est propre et optimisé. C'est un développeur compétent, je recommande fortement Danih.",recommandation_name5:"Philibert Hemmy Ramananjato · 1er",recommandation_post5:"Ingénieur développement logiciels",recommandation_date5:"Mis en ligne le : 19 septembre 2024",recommandation_function5:"Philibert Hemmy et Danih Stephane ont fréquenté la même école",recommandation_desc5:"Il est un excellent coéquipier, toujours soucieux de tenir ses engagements et prêt à aider quand c’est nécessaire. Nous avons souvent travaillé ensemble dans la même équipe. C'est un bénévole dévoué qui prend ses responsabilités très au sérieux. Il est patient et toujours fiable. Il a également un grand sens de l'humour, ce qui est un vrai soulagement, surtout quand les choses ne se passent pas comme prévu.",recommandation_name6:"Masinavalona EMIR TOLOJANAHARY · 1er",recommandation_post6:"Développeur PHP/Javascript",recommandation_date6:"Mis en ligne le : 1 octobre 2024",recommandation_function6:"Masinavalona EMIR travaillait avec Danih Stephane dans la même équipe",recommandation_desc6:"Danih s'est rapidement intégré à l'équipe de notre projet chez eTech, adoptant avec aisance nos processus et outils. Toujours à l'écoute, il fait preuve d'une grande flexibilité pour s'adapter aux besoins de l'équipe. Sa persévérance face aux défis et son engagement constant sont impressionnants, ce qui en fait un collaborateur fiable et un atout précieux. \n Doté d'un excellent esprit d'équipe, Danih apporte une énergie positive qui renforce la dynamique du groupe.  \n L'une de ses récentes initiatives a été de s'intéresser à l'évolution de l'intelligence artificielle et de l'intégrer avec aisance dans les tâches quotidiennes du développeur, optimisant ainsi notre efficacité. \n Sa curiosité et sa volonté d'apprendre lui permettent de progresser rapidement et de contribuer de manière significative à chaque projet.  \n Je le recommande vivement.",popup_image1title:"Technologie PHP 8",popup_image1:"PHP 8 est utilisé pour orchestrer l'automatisation des processus ETL, notamment en facilitant l'extraction, la transformation et le chargement des données. Grâce à ses nouvelles fonctionnalités, telles que le compilateur JIT et les arguments nommés, PHP 8 optimise la manipulation des données complexes et assure un traitement efficace. Les propriétés typées et la gestion stricte des erreurs garantissent également la fiabilité et la robustesse des scripts ETL.",popup_image2title:"Technologie Laravel 8",popup_image2:"Laravel 8 est utilisé comme base pour structurer et orchestrer les processus ETL, offrant un environnement robuste et bien organisé pour l'extraction, la transformation et le chargement des données. Grâce à ses fonctionnalités avancées telles que les jobs planifiés (scheduling), les queues pour gérer les tâches en arrière-plan, et son puissant ORM Eloquent, Laravel facilite la gestion de gros volumes de données et assure un traitement efficace et sécurisé. Le framework permet également une intégration fluide avec divers systèmes de stockage et des bases de données relationnelles, tout en rendant le développement rapide et maintenable grâce à son architecture modulaire et évolutive.",popup_image3title:"Technologie Docker",popup_image3:"Docker est utilisé pour containeriser l'ensemble des processus ETL, assurant ainsi un environnement isolé et cohérent pour l'extraction, la transformation et le chargement des données. Chaque composant de la chaîne ETL (base de données, scripts de traitement, stockage) est encapsulé dans des conteneurs, garantissant une portabilité et une reproductibilité parfaites entre les environnements de développement, de test et de production. Docker permet également de simplifier le déploiement et la gestion des dépendances, tout en optimisant l'utilisation des ressources grâce à l'orchestration des conteneurs, assurant ainsi une exécution fluide et scalable du pipeline ETL.",popup_image4title:"Jenkins",popup_image4:"Jenkins est utilisé pour automatiser le déploiement et l'intégration continue (CI/CD) dans le cadre du projet ETL. Grâce à ses pipelines configurables, Jenkins permet de planifier et d'exécuter les tests, les builds et les déploiements, garantissant ainsi que les processus ETL soient systématiquement testés et déployés dans un environnement contrôlé. Cela assure une livraison continue et fiable des fonctionnalités, avec des retours rapides sur les éventuels problèmes.",popup_image5title:"Bitbucket",popup_image5:"Bitbucket sert de plateforme Git pour la gestion des versions et la collaboration sur le code source du projet ETL. Les fonctionnalités comme les pull requests et les pipelines Bitbucket CI permettent aux équipes de suivre les modifications du code et de garantir un développement sécurisé et transparent. Bitbucket s'intègre également avec d'autres outils de l'écosystème comme Jira et Confluence, facilitant ainsi une gestion efficace des projets.",popup_image6title:"Linux Debian",popup_image6:"Linux Debian est le système d'exploitation choisi pour héberger l'infrastructure du projet ETL. Connu pour sa stabilité, sa sécurité et sa grande compatibilité avec les technologies open-source, Debian assure un environnement fiable pour exécuter les conteneurs Docker, orchestrer les processus ETL, et gérer les différentes bases de données et services requis.",popup_image7title:"PHPUnit avec Sail",popup_image7:"PHPUnit est utilisé pour assurer la qualité du code dans le cadre du développement des processus ETL. Avec Laravel Sail, un environnement de développement local basé sur Docker, il est facile de configurer et d'exécuter des tests unitaires de manière cohérente et isolée. Cela garantit que chaque composant de l'ETL fonctionne comme prévu avant d'être intégré au pipeline principal.",popup_image8title:"Atlassian (Gestion de Projet)",popup_image8:"Atlassian est utilisé pour la gestion du projet ETL, permettant de suivre les tâches, les développements, les délais et les objectifs. Grâce à son intégration avec des outils tels que Jira et Confluence, Atlassian facilite une collaboration transparente entre les équipes, assurant que chaque étape du processus ETL soit bien documentée, suivie et réalisée dans les délais impartis.",popup_image9title:"Jira",popup_image9:"Jira est utilisé pour suivre les tâches et les incidents liés au développement du pipeline ETL. Chaque étape du processus, de l'extraction à la transformation et au chargement, est gérée et assignée dans Jira, permettant un suivi transparent et une gestion efficace des priorités. Les workflows personnalisés aident à optimiser les processus, avec des sprints pour gérer les cycles de développement.",popup_image10title:"Confluence (Atlassian)",popup_image10:"Confluence est utilisé pour la documentation et la collaboration autour du projet ETL. Chaque partie du processus, des détails techniques aux décisions de conception, est documentée dans Confluence, permettant à l'équipe de rester informée et à jour. Cette plateforme centralisée facilite également le partage des connaissances et la révision des informations critiques.",popup_image11:"La méthodologie ETL repose sur Laravel pour orchestrer les étapes d'extraction, de transformation et de chargement. Laravel simplifie la création de pipelines ETL modulaires et extensibles, avec une gestion facile des tâches programmées et des files d'attente pour traiter les données en arrière-plan. Les fonctionnalités intégrées, telles que l'ORM Eloquent, facilitent la manipulation et la transformation des données avant de les charger dans un entrepôt central.",popup_image11title:"Méthodologie ETL avec Laravel",popup_image12:"Le projet ETL consiste à automatiser l'extraction des données de diverses sources (CSV, SQL), à les transformer par des processus complexes (nettoyage, enrichissement, génération de fonctionnalités), puis à les charger dans un entrepôt de données centralisé. Le processus ETL vise à rendre les données disponibles pour des analyses et visualisations en temps réel, garantissant ainsi une prise de décision basée sur des informations fiables et actualisées.",popup_image12title:"Résumé général de l'ETL",popup_image13:"Un tableau de bord graphique est intégré depuis un autre projet lié pour visualiser les mouvements et les statistiques, alimenté par l'ETL et les données disponibles. Grâce à cet outil, les utilisateurs peuvent surveiller chaque transaction, observer les mouvements des données (particulièrement les transformations), identifier les anomalies ou les goulets d'étranglement, et obtenir des insights immédiats sur les données transformées.",popup_image13title:"Dashboard graphique de gestion",popup_image14:"Tous les projets liés à l'ETL sont également conçus sous forme de microservices, chaque composant du pipeline étant découplé et communiquant via des API REST. Cela permet une flexibilité, modularité et évolutivité accrues du système. Chaque microservice gère une partie du processus (extraction, transformation ou chargement) et peut être déployé et mis à jour indépendamment, tout en interagissant de manière fluide avec les autres composants via des API standardisées.",popup_image14title:"Microservice avec l'API",popup_image15:"JavaScript ES6 permet d'améliorer la gestion de la logique côté client en introduisant des fonctionnalités modernes comme les classes, les modules, les promesses, et des raccourcis syntaxiques. Pour ce projet, l'ES6 facilite la manipulation du DOM, la gestion des événements utilisateur et l'envoi de requêtes asynchrones à l'API. Ces fonctionnalités permettent d'améliorer la fluidité et la réactivité de l'interface utilisateur.",popup_image15title:"JavaScript ES6 (ECMAScript 6)",popup_image16:"jQuery simplifie les interactions avec le DOM, la gestion des animations, les requêtes AJAX et la manipulation d'événements. Bien qu'ES6 offre des alternatives natives, jQuery est toujours utile pour assurer la compatibilité avec les anciens navigateurs et simplifier certaines tâches complexes. Dans ce projet, jQuery peut être utilisé pour gérer des composants interactifs rapidement et efficacement.",popup_image16title:"jQuery",popup_image17:"Webpack est un module bundler qui facilite la gestion des dépendances et la compilation des fichiers JavaScript, CSS, images, et autres ressources dans le projet. Pour une application SaaS, Webpack peut être utilisé pour optimiser les performances en créant des bundles de fichiers compressés et en chargeant dynamiquement les composants nécessaires, ce qui améliore le temps de chargement de l'application.",popup_image17title:"Webpack",popup_image18:"Metronic 8 est un tableau de bord d'administration basé sur Bootstrap, conçu pour être facilement intégré dans des applications web. Dans ce projet, Metronic 8 permet de créer une interface utilisateur soignée et moderne pour les utilisateurs de l'application SaaS, avec des composants prêts à l'emploi pour les graphiques, les formulaires et les tableaux de bord statistiques.",popup_image18title:"Metronic 8 Dashboard",popup_image19:"PHP 8 offre des améliorations significatives en termes de performances grâce à son compilateur JIT (Just-In-Time). Dans le cadre du projet, PHP 8 permet d'optimiser les opérations backend pour la gestion et le traitement des données, en particulier pour les tâches de collecte et d'analyse statistique. De plus, les nouvelles fonctionnalités comme les Union Types, Named Arguments et les Attributes permettent une écriture de code plus flexible et lisible.",popup_image19title:"PHP version 8",popup_image20:"SSH (Secure Shell) est un protocole qui permet d’administrer les serveurs à distance de manière sécurisée. Dans ce projet, SSH est utilisé pour le déploiement, la gestion et la maintenance de l'application sur le serveur, garantissant la sécurité des connexions et des transferts de données lors des mises à jour ou des configurations.",popup_image20title:"Serveur SSH",popup_image21:"SCRUM est une méthodologie Agile utilisée pour la gestion de projets complexes, notamment en développement logiciel. Dans le contexte de l'optimisation d'une application SaaS, SCRUM permet de structurer et d'organiser le travail en petites itérations appelées sprints, ce qui permet de livrer rapidement des fonctionnalités utilisables et d'obtenir des retours réguliers des utilisateurs ou parties prenantes. SCRUM favorise la collaboration entre les équipes, assure une adaptation continue aux changements et améliore la qualité du produit final.",popup_image21title:"SCRUM",popup_image22:"Laravel est un framework PHP utilisé pour le traitement backend du projet. Il offre une architecture MVC qui facilite le développement rapide d’applications web robustes. Pour ce projet, Laravel permet de structurer les requêtes API, de gérer les bases de données et de mettre en place des systèmes de validation, tout en intégrant des fonctionnalités comme les notifications, les files d'attente (queues), et la gestion des utilisateurs.",popup_image22title:"Traitement Backend avec Laravel",popup_image23:"Jetstream et Breeze sont des options d'authentification, accompagnées de rôles et permissions configurés via des politiques. La protection CSRF est activée, les données sont validées avec rigueur, et les mots de passe sont chiffrés avec bcrypt. Les fichiers sont stockés en toute sécurité, les données sensibles sont cryptées, et une protection contre les attaques XSS est assurée en échappant les données dans les vues. Un audit des actions utilisateurs est implémenté, avec une limitation des tentatives de connexion pour prévenir les attaques par force brute.",popup_image23title:"Sécurité Laravel",popup_image24:"Le code est structuré de façon modulaire pour une architecture claire. Les migrations sont utilisées pour la base de données, et le scheduler pour automatiser les tâches. Les configurations sont gérées avec des fichiers .env, tandis que les déploiements sont automatisés via des pipelines CI/CD. PHPUnit est utilisé pour les tests automatisés, et des caches comme Redis ou Memcached optimisent les performances.",popup_image24title:"Gestion Laravel",popup_image25:"XML est utilisé pour créer l'interface utilisateur avec des layouts comme ConstraintLayout. L'application assure une accessibilité optimale avec des descriptions de contenu, en suivant les bonnes pratiques d'accessibilité. La cohérence visuelle est maintenue grâce aux styles et thèmes XML, et des animations sont ajoutées pour dynamiser l'interface.",popup_image25title:"Affichage Android avec XML",popup_image26:"Orchid est un ERP bancaire, permettant de gérer les comptes clients, transactions, prêts et crédits. Il intègre des fonctions de gestion des risques et de conformité. Utilisé comme backend pour une application bancaire, il expose des API pour synchroniser les données en temps réel et est déployé sur des serveurs robustes avec des bases de données comme Oracle ou MySQL.",popup_image26title:"Système Orchid (ERP bancaire)",popup_image27:"Java est un langage clé pour le développement Android, favorisant la programmation orientée objet et l'intégration avec l'Android SDK. Les threads sont utilisés pour les tâches lourdes, et des services d'arrière-plan assurent la réactivité de l'application même en inactivité. La gestion des événements système via BroadcastReceiver optimise l'expérience utilisateur.",popup_image27title:"Langage JAVA pour Android",popup_image28:"WSO2 est une solution open source de gestion d'API, sécurisant les accès et surveillant les performances. Dans une application bancaire, il sert de passerelle entre le front-end et le backend (ERP Orchid), en gérant l'authentification via OAuth2 ou JWT. Il permet la publication et le versionnage des API, tout en offrant des outils de surveillance pour analyser les performances et sécuriser les services bancaires.",popup_image28title:"WSO2 API Manager",popup_image29title:"Symfony — Backend Senior",popup_image29:"Symfony est utilisé comme framework backend robuste dans ce rôle Senior. Il assure la solidité de l'architecture API, la gestion des entités complexes et l'intégration avec les modules cartographiques et IA. Sa maturité et ses composants découplés garantissent performance et scalabilité.",popup_image30title:"WebSocket & Mercure — Temps Réel",popup_image30:"Le protocole WebSocket via Mercure est utilisé pour diffuser en temps réel les données de suivi cartographique. Il permet une communication bidirectionnelle persistante entre serveur et clients, garantissant des mises à jour instantanées sur la carte sans polling.",popup_image31title:"Symfony & API REST — Plateforme de Réservation",popup_image31:"Symfony avec API Platform sert de backend RESTful sécurisé pour la plateforme de réservation. Il gère la logique métier complexe : disponibilité des véhicules, statuts de réservation, intégration des paiements et génération automatique des confirmations.",popup_image32title:"Symfony 7 — Mentorat & Architecture",popup_image32:"Symfony 7 est au cœur des projets mentorisés, offrant un cadre structuré pour l'enseignement de l'architecture moderne. Il permet d'illustrer les concepts de DDD, CQRS et d'intégration d'IA directement dans un framework professionnel éprouvé.",popup_image33title:"Docker — Environnements Reproductibles",popup_image33:"Docker est utilisé pour créer des environnements de développement reproductibles, idéaux pour l'enseignement et l'intégration de modèles IA locaux (Ollama). Chaque stack (Symfony, Redis, Mercure, IA) est containerisée, permettant un déploiement instantané et une isolation complète.",popup_image34title:"Next.js — SSR & App Router",popup_image34:"Next.js est le framework React de référence utilisé dans le rôle Senior pour les interfaces full-stack. Il permet le rendu côté serveur (SSR), la génération statique (SSG) et l'App Router pour une architecture modulaire, garantissant performance et SEO optimal.",popup_image35title:"React — Composants & État",popup_image35:"React est utilisé pour construire l'interface utilisateur sous forme de composants réutilisables. La gestion d'état avancée (Context API, hooks personnalisés) permet de piloter les données cartographiques en temps réel et les interactions complexes.",popup_image36title:"TypeScript — Typage Statique",popup_image36:"TypeScript apporte un typage statique strict à l'ensemble du codebase, réduisant les erreurs à la compilation. Dans ce rôle Senior, il garantit la maintenabilité du code, facilite les code reviews et assure la robustesse des interfaces entre modules.",popup_image37title:"Claude AI — Intégration IA",popup_image37:"L'IA Anthropic Claude est intégrée pour enrichir les modules métier : génération de résumés, aide à la décision et automatisation de tâches complexes. L'API Claude est consommée côté backend Symfony, garantissant sécurité et contrôle des appels.",popup_image38title:"Mercure — Push Temps Réel",popup_image38:"Le protocole Mercure (basé sur SSE) est utilisé pour diffuser en temps réel les événements cartographiques et les notifications métier. Il remplace le polling inefficace par un push serveur natif, intégré nativement avec Symfony.",popup_image39title:"Next.js — Interface de Réservation",popup_image39:"Next.js structure l'interface de réservation avec l'App Router, offrant une navigation fluide, un rendu hybride SSR/CSR et une optimisation automatique des images et ressources pour un chargement ultra-rapide.",popup_image40title:"React — UX Dynamique",popup_image40:"React est utilisé pour le filtrage dynamique des véhicules, l'affichage en temps réel des disponibilités et la gestion du parcours de réservation, avec un état local optimisé pour les interactions rapides.",popup_image41title:"REST API — API Platform",popup_image41:"API Platform (sur Symfony) génère automatiquement les endpoints RESTful documentés. Il gère les ressources véhicules, réservations et paiements avec validation, sérialisation et sécurité JWT intégrées.",popup_image42title:"SEO — Visibilité & Performance",popup_image42:"Le SEO est optimisé via Next.js : métadonnées dynamiques, sitemap automatique, rendu SSR pour l'indexation Google et optimisation Core Web Vitals. Résultat : meilleure visibilité et plus de trafic organique.",popup_image43title:"React — Projets Mentorisés",popup_image43:"React est la technologie centrale enseignée lors du mentorat. Les juniors apprennent les composants fonctionnels, les hooks (useState, useEffect, useContext) et les patterns professionnels à travers des projets concrets.",popup_image44title:"Tailwind CSS — Design Utilitaire",popup_image44:"Tailwind CSS est utilisé pour construire des interfaces modernes rapidement grâce à ses classes utilitaires. Il est enseigné comme alternative à Bootstrap, favorisant un design cohérent sans CSS personnalisé superflu.",popup_image45title:"Mercure — Temps Réel en Mentorat",popup_image45:"Le protocole Mercure est intégré dans les projets mentorisés pour initier les équipes au temps réel. Il illustre concrètement comment remplacer le polling par du push serveur dans une architecture Symfony.",popup_image46title:"Claude AI — Solutions IA Locales",popup_image46:"Des solutions IA locales basées sur Ollama (LLaMA, Mistral) et l'API Claude sont intégrées dans les projets. Elles permettent d'automatiser la génération de code, les tests et l'assistance technique sans dépendre du cloud.",popup_image47title:"shadcn/ui — Composants UI Modernes",popup_image47:"shadcn/ui est utilisé dans le rôle Senior pour accélérer la construction d'interfaces professionnelles avec des composants accessibles, personnalisables et non-bundlés. Il s'intègre nativement avec Next.js, Tailwind CSS et TypeScript, garantissant cohérence visuelle et maintenabilité du design system.",popup_image48title:"PMO — Pilotage de Projet",popup_image48:"En tant que PMO (Project Management Officer), je coordonne le cycle de vie complet des projets : cadrage, planification, suivi des roadmaps, gestion des risques et mise en production. Je suis l'interface stratégique entre les équipes techniques et les directions métier, assurant alignement des objectifs et livraison dans les délais.",popup_image49title:"shadcn/ui — Interface de Réservation",popup_image49:"shadcn/ui a été utilisé pour construire rapidement l'interface de la plateforme de réservation : formulaires multi-étapes, modales, sélecteurs de dates et tableaux de bord. Sa compatibilité native avec Next.js et Tailwind a permis un développement fluide et un rendu soigné.",popup_image50title:"Leaflet — Cartes Interactives",popup_image50:"Leaflet (via React-Leaflet) est le moteur de cartographie d'AGREETECH. Il affiche les zones agricoles, gère les couches de données géospatiales et s'intègre avec Leaflet Draw pour permettre le dessin interactif de polygones, rectangles et marqueurs directement sur la carte.",popup_image51title:"Google Earth Engine — Imagerie Satellite",popup_image51:"Google Earth Engine est utilisé pour l'analyse d'imagerie satellite à grande échelle. Il permet d'interroger des indices de végétation (NDVI), d'analyser l'occupation des sols, de détecter les changements climatiques et d'extraire des indicateurs environnementaux sur les zones agricoles dessinées.",popup_image52title:"Turf.js — Calculs Géospatiaux",popup_image52:"Turf.js réalise tous les calculs géospatiaux côté client : calcul de surface et périmètre des zones dessinées, détermination du centroïde, validation des géométries GeoJSON, intersections et buffers. Son exécution côté browser garantit une réponse instantanée sans appel serveur.",popup_image53title:"React 19 — Interface Agentique",popup_image53:"React 19 avec ses nouvelles fonctionnalités (Server Components, Actions, use()) structure l'interface d'AGREETECH. Les composants géospatiaux (carte, panneaux d'analyse, visualisations) sont construits de façon modulaire et réactive, garantissant fluidité et maintenabilité.",popup_image54title:"TypeScript 5.8 — Géométries Typées",popup_image54:"TypeScript 5.8 type l'ensemble des structures géospatiales : interfaces GeoJSON (Feature, FeatureCollection, Geometry), types Redux et API REST. Le typage strict prévient les erreurs sur les coordonnées et garantit l'intégrité des données géographiques tout au long du pipeline.",popup_image55title:"Redux Toolkit — État Applicatif",popup_image55:"Redux Toolkit gère l'état global d'AGREETECH : zones dessinées, résultats d'analyse, état de la carte, filtres et navigation. Ses slices structurés et son immuabilité garantissent une gestion prévisible des données géospatiales complexes.",popup_image56title:"React Query — Données Serveur",popup_image56:"TanStack React Query synchronise les données entre le frontend et l'API REST avec cache intelligent, re-fetching automatique et gestion des états de chargement/erreur. Il optimise les requêtes vers l'API GeoJSON et Google Earth Engine.",popup_image57title:"Material-UI — Design System",popup_image57:"Material-UI (MUI v7) avec Emotion fournit le design system complet d'AGREETECH : panneaux d'analyse, formulaires de configuration, drawers cartographiques et tableaux de bord. Son thème personnalisé assure une cohérence visuelle professionnelle.",popup_image58title:"Vite — Build Ultra-Rapide",popup_image58:"Vite 7 assure un démarrage instantané du serveur de développement et des builds de production optimisés pour AGREETECH. Son HMR (Hot Module Replacement) ultra-rapide accélère le cycle de développement des composants cartographiques complexes.",popup_image59title:"Chart.js — Visualisation Environnementale",popup_image59:"Chart.js (via react-chartjs-2) visualise les données environnementales extraites : graphiques NDVI temporels, histogrammes d'occupation des sols, courbes climatiques et indicateurs agricoles. Les graphiques sont synchronisés avec les zones sélectionnées sur la carte.",what_i_offer:"Ce que je propose",mes_services:"Mes Services",backend:"Backend",architecture_robuste_apis_performantes:"Architecture robuste et APIs performantes",apis_restful:"APIs RESTful",authentification_securisee:"Authentification sécurisée",integration_paiement:"Intégration paiement",cms_sur_mesure:"CMS sur mesure",optimisation_bdd:"Optimisation BDD",frontend:"Frontend",interfaces_modernes_reactives:"Interfaces modernes et réactives",applications_spa:"Applications SPA",ui_ux_responsive:"UI/UX responsive",animations_fluides:"Animations fluides",dashboards_interactifs:"Dashboards interactifs",performance_optimisee:"Performance optimisée",specialises:"Spécialisés",solutions_techniques_sur_mesure:"Solutions techniques sur mesure",ecommerce_avance:"E-commerce avancé",systemes_de_reservation:"Systèmes de réservation",applications_metier:"Applications métier",automatisation:"Automatisation",seo_technique:"SEO technique",maintenance:"Maintenance",support_optimisation_continue:"Support et optimisation continue",maintenance_preventive:"Maintenance préventive",securite_renforcee:"Sécurité renforcée",performance_optimale:"Performance optimale",support_reactif:"Support réactif",monitoring_24_7:"Monitoring 24/7",conseil:"Conseil",expertise_technique_strategique:"Expertise technique et stratégique",audit_approfondi:"Audit approfondi",architecture_systeme:"Architecture système",securite_avancee:"Sécurité avancée",analyse_strategique:"Analyse stratégique",formation_equipe:"Formation équipe",autres_services:"Autres Services",services_devops:"Services DevOps",services_tests_qualite:"Services de Tests & Qualité",services_r_d_technologique:"Services de R&D Technologique",accompagnement_croissance_digitale:"Accompagnement en Croissance Digitale",solutions_cloud:"Solutions Cloud","publish-date1":"15 Novembre 2021","publish-date2":"11 Avril 2022","publish-date3":"23 Mai 2022","publish-date4":"8 Mai 2023","publish-date5":"21 Juin 2023","publish-date6":"14 Août 2023","publish-date7":"30 Juin 2024"},en:{home:"Home.",about:"About.",skills:"Skills.",portfolio:"Portfolio.",contact:"Contact.",yo:"Hello !",presentation:"My name is Danih Stephane",engineer:"Engineer",developer:"Developer",coder:"Coder",get_in_touch:"Get in touch",years_of_experience:"Years of experience",completed_projects:"Completed projects",happy_clients:"Happy clients",about_me:"About me",title_introduction:"Innovative application solution? Let's realize your ideas!",introduction:"Hello 👨‍💻, I'm Danih Stéphane Rakotoarison Harilanto, a confirmed application developer. Passionate about information technology, I have worked on various projects, including SaaS solutions and cloud services. My expertise covers full stack development and collaboration with creative teams, aiming to transform ideas into concrete solutions. Whether working solo or in a team, I focus on effective project management, agility, and open communication to ensure success.",hire_me:"Hire me",download_cv:"Download CV",my_skills:"My skills",title_skills:"What are the ranges of my technical skills in development?",skills_desc:"Here are the technical abilities and development tools that enable me to transform concepts into functional and intuitive web applications, combining mastery of programming languages, modern frameworks, and optimized development environments.",skills_button:"Skills",tools_button:"Tools",my_experiences:"Professional",experience_title:"Over 5 years of experience in the industry with a strong involvement in personal projects",experience_introduction:"I have had the opportunity to work on various projects, primarily in the field of SaaS solutions and cloud services. During these experiences, I have been involved in several tasks and responsibilities, ranging from developing specific features to optimizing system architecture. This immersion has allowed me to gain a solid understanding of the technical challenges and best practices associated with these dynamic environments.",june_2023_present:"June 2023 - Present 2024",first_box_title:"Data Management with ETL",first_box_description:"Extraction: \n Integration of various data (CSV, SQL). \n Scheduled and regular data extraction. \n Preprocessing to correct and normalize formats. \n \n Transformation: \n Application of complex transformations via pipelines. \n Data cleaning and enrichment. \n Creation of new features from raw data. \n \n Loading: \n Storage of data in a central warehouse. \n Availability of data for analysis and visualization.",techno:"Development ecosystem",june_2022_june_2023:"June 2022 - June 2023",second_box_title:"Optimization of a SaaS",second_box_description:"Improvement of the web application for data management to enhance the efficiency and accuracy of statistical collection. This project aims to integrate advanced features to facilitate data entry, processing, and analysis while ensuring an intuitive and user-friendly interface.",specifications:"Specifications",specifications_descriptions:"Project management for collection: database, interface with the client ecosystem, check processing, marketing targeting, and data visualization.",feb_2022_mai_2022:"Feb 2022 - May 2022",third_box_title:"Revision of a Data Entry Interface",third_box_description:"Correction and improvement of a data entry tool, incorporating advanced validations, the ability to import files, export of processed data, and user management with access rights.",technical:"Technical references",aug_2021_des_2021:"Aug 2021 - Dec 2021",fourth_box_title:"Java Developer",fourth_box_description:"Mobile Banking, native Android application, enhances accessibility and convenience of banking services, allowing users to manage their finances anytime and anywhere.",characteristics:"Characteristics",nov_2024_jan_2025:"Nov. 2024 - Jan. 2025",seventh_box_title:"AI Developer & Mentor",seventh_box_role:"Technical Mentoring & AI Integration",seventh_box_description:"AI Developer and Technical Mentor specializing in React and Symfony solutions. Team coaching, local AI integration (Ollama), scalable architecture with Docker and Mercure for real-time features, and implementation of development best practices.",jan_2025_jun_2025:"Jan. 2025 - Jun. 2025",sixth_box_title:"Vehicle Booking Platform Redesign",sixth_box_role:"Fullstack Architect & Performance",sixth_box_description:"Full redesign of a vehicle rental platform: ultra-reactive Next.js/React interface, secure Symfony backend, smart vehicle filtering, mobile banking payments, custom back-office dashboard and SEO optimization. Results: +40% bookings, -30% abandon rate, -50% loading time.",nov_2025_present:"Nov. 2025 - Present",eighth_box_title:"Agentic AI & Geospatial Analysis",eighth_box_role:"AGREETECH Project",eighth_box_description:"Development of an agentic geospatial analysis platform within the AGREETECH project. Design of modules enabling interactive drawing of agricultural zones on a map, satellite imagery analysis via Google Earth Engine, advanced geospatial calculations (area, perimeter, centroid) with Turf.js, and environmental data visualization via Chart.js. React 19 + TypeScript architecture, Redux Toolkit for app state, React Query for server state, Material-UI and Vite build.",jul_2025_present:"Jul. 2025 - Present",fifth_box_title:"Lead Technical & PMO — AI and Real-Time Mapping",fifth_box_role:"Lead Technical & PMO AI",fifth_box_description:"Promoted to Senior Developer following a rigorous internal assessment. As Lead Technical and PMO, I drove critical modules integrating real-time mapping and AI, led code reviews, managed the full project lifecycle and acted as strategic bridge between technical teams and business stakeholders.",my_education:"My background",education_title:"How can an educational journey lead to excellence in technology?",education_description:"During my educational journey in computer development, I had the opportunity to earn a master's degree from one of the best universities in Europe, where I deepened my theoretical and practical knowledge. This experience allowed me to strengthen my application development skills while benefiting from a solid computer science education provided by local universities. At the same time, I acquired a rigorous foundation in mathematics, essential for solving complex problems and optimizing algorithms, thus preparing me to tackle the technical challenges of the industry.",education_first_box_title:"University of Côte d'Azur",education_first_box_description:"Computer Engineering. Track in Mobility, Big Data, and Systems Integration (MBDS)",license:"License",education_second_box_title:"IT University",education_second_box_descirption:"Bachelor's degree in Information Technology. Specialized in application development or programming.",academic:"Academic",education_third_box_title:"Faculty of Mathematical Sciences",education_third_box_description:"Analysis, Algebra, Geometry, Probability and Statistics, Logic, Proof, as well as Vector and Matrix Calculus.",intensive_courses:"Intensive Courses",languages:"Languages",malagasy:"Malagasy (MG)",french:"French (FR)",french_desc:"/ 2nd native",english:"English (EN)",english_desc:"Professional proficiency",german:"German (DE)",german_desc:"Beginner",my_works:"My Works",my_works_title:"Innovative Solutions that Defy Expectations: My Projects",my_works_introduction:"Designing exceptional websites that blend functionality and aesthetics, ensuring long-term usability for users. Developing a carefully crafted, clear, and well-documented interface that ensures smooth and intuitive interactions. The goal is to create elegant solutions that meet current client needs and prepare them for the future.",load_more_work:"Load More Work",recommandation_title:"Curious to know what my colleagues say about me? Here are their thoughts!",recommandation_introduction:"As I seek new professional opportunities, I would like to share with you the recommendations from my colleagues and mentors. Their feedback reflects my skills, work ethic, and ability to collaborate effectively in a team. Each testimonial highlights a unique experience, showcasing the qualities that make me an ideal candidate for a developer position.",recommandation_conclusion:"You can add recommendations on LinkedIn",contact_title:"Do you have an idea or a project? Feel free to leave me a message!",contact_desc:"For any assistance, don't hesitate to contact me and let me know how I can help you. Fill out the form, and I will respond to you as soon as possible.",address:"Address:",phone:"Phone:",phone_form:"Phone (Optional)",name:"Name",ex_name:"ex. John Doe",ex_email:"ex. john.doe@gmail.com",optional:"Phone Number",write_a_message:"Write a Message",send:"Send",proundly:"Crafted with Passion, Powered by Innovation",recommandation_name1:"Diary Razafinjatovo · 1st",recommandation_post1:"Project Manager / Certified Product Owner | Scrum Master",recommandation_date1:"Posted on: September 24, 2024",recommandation_function1:"Diary was Danih Stephane's direct manager",recommandation_desc1:"I had the pleasure of working with Danih as his manager, and I can affirm that he is an exceptional professional. Passionate and always seeking innovation, he constantly brought creative solutions to every project he contributed to. \n He stands out for his seriousness, commitment, and ability to anticipate project needs while proposing innovative ideas. Whether it's solving complex problems or optimizing development processes, he always found effective solutions. \n His passion for development and attention to detail make him a valuable asset to any team. \n I highly recommend him.",recommandation_name2:"ZAFIMANANGA Josio Rigonolde · 1st",recommandation_post2:"PHP Developer (Symfony, WordPress, ...) / ReactJs",recommandation_date2:"Posted on: September 23, 2024",recommandation_function2:"ZAFIMANANGA worked with Danih Stephane in the same team",recommandation_desc2:"I had the pleasure of closely collaborating with Danih, who demonstrated perseverance in every task assigned to him. Even in the face of challenges, he showed great determination. \n Within our team at eTech, he quickly adapted to the processes and development tools in place. His ability to easily integrate into a constantly evolving environment is a valuable quality that allows him to contribute effectively to collective projects. \n Danih quickly found his place within our team thanks to his excellent team spirit. Always ready to collaborate and share his ideas, he brought positive energy that strengthened the group dynamic. \n He is constantly interested in improving his skills, which enables him to progress rapidly and contribute significantly to each project.",recommandation_name3:"Njaratiana Herivola RAZAFINDRABE · 1st",recommandation_post3:"Tech Lead (PHP/Symfony/Laravel) | Scrum Master | Product Owner",recommandation_date3:"Posted on: September 20, 2024",recommandation_function3:"Njaratiana Herivola was Danih Stephane's direct manager",recommandation_desc3:"Danih is a passionate developer, very reactive and proactive at the same time. He communicates well with both the team and our clients. He is also a good mentor for the interns who worked in the team. Most of the time, he surprises us with extra projects that highlight his passion for AI. I strongly recommend him. He will make a great lead developer ;)",recommandation_name4:"Onintsoa Randriamiarinamanana · 1st",recommandation_post4:"IT Developer",recommandation_date4:"Posted on: September 19, 2024",recommandation_function4:"Onintsoa worked with Danih Stephane in the same team",recommandation_desc4:"I had the opportunity to collaborate with Danih on several projects, and his programming skills are remarkable. His code is clean and optimized. He is a competent developer, and I highly recommend Danih.",recommandation_name5:"Philibert Hemmy Ramananjato · 1st",recommandation_post5:"Software Development Engineer",recommandation_date5:"Posted on: September 19, 2024",recommandation_function5:"Philibert Hemmy and Danih Stephane attended the same school",recommandation_desc5:"He is an excellent teammate, always committed to fulfilling his obligations and ready to help when necessary. We often worked together in the same team. He is a dedicated volunteer who takes his responsibilities very seriously. He is patient and always reliable. He also has a great sense of humor, which is a real relief, especially when things don't go as planned.",recommandation_name6:"Masinavalona EMIR TOLOJANAHARY · 1st",recommandation_post6:"PHP/Javascript Developer",recommandation_date6:"Posted on: October 1, 2024",recommandation_function6:"Masinavalona EMIR worked with Danih Stephane in the same team",recommandation_desc6:"Danih quickly integrated into our project team at eTech, adopting our processes and tools with ease. Always attentive, he demonstrates great flexibility in adapting to the team's needs. His perseverance in the face of challenges and constant commitment are impressive, making him a reliable collaborator and a valuable asset. \n With an excellent team spirit, Danih brings positive energy that strengthens the group's dynamic. \n One of his recent initiatives was showing interest in the evolution of artificial intelligence and integrating it seamlessly into a developer's daily tasks, thus optimizing our efficiency. \n His curiosity and desire to learn allow him to progress quickly and contribute significantly to each project. \n I highly recommend him.",popup_image1:"PHP 8 is used to orchestrate the automation of ETL processes, particularly by facilitating the extraction, transformation, and loading of data. With its new features, such as the JIT compiler and named arguments, PHP 8 optimizes the manipulation of complex data and ensures efficient processing. Typed properties and strict error handling also guarantee the reliability and robustness of ETL scripts.",popup_image1title:"PHP 8 Technology",popup_image2:"Laravel 8 is used as a foundation to structure and orchestrate ETL processes, providing a robust and well-organized environment for data extraction, transformation, and loading. With advanced features such as scheduled jobs, queues for managing background tasks, and its powerful Eloquent ORM, Laravel facilitates the handling of large data volumes and ensures effective and secure processing. The framework also allows seamless integration with various storage systems and relational databases while making development fast and maintainable due to its modular and scalable architecture.",popup_image2title:"Laravel 8 Technology",popup_image3:"Docker is used to containerize all ETL processes, ensuring an isolated and consistent environment for data extraction, transformation, and loading. Each component of the ETL chain (database, processing scripts, storage) is encapsulated in containers, guaranteeing perfect portability and reproducibility between development, testing, and production environments. Docker also simplifies deployment and dependency management while optimizing resource use through container orchestration, ensuring smooth and scalable execution of the ETL pipeline.",popup_image3title:"Docker Technology",popup_image4:"Jenkins is used to automate deployment and continuous integration (CI/CD) within the ETL project. With its configurable pipelines, Jenkins allows scheduling and executing tests, builds, and deployments, ensuring that ETL processes are systematically tested and deployed in a controlled environment. This guarantees continuous and reliable delivery of features, with quick feedback on any issues.",popup_image4title:"Jenkins",popup_image5:"Bitbucket serves as a Git platform for version control and collaboration on the ETL project’s source code. Features like pull requests and Bitbucket CI pipelines enable teams to track code changes and ensure secure and transparent development. Bitbucket also integrates with other tools in the ecosystem like Jira and Confluence, facilitating effective project management.",popup_image5title:"Bitbucket",popup_image6:"Linux Debian is the chosen operating system to host the ETL project infrastructure. Known for its stability, security, and broad compatibility with open-source technologies, Debian ensures a reliable environment for running Docker containers, orchestrating ETL processes, and managing the various databases and services required.",popup_image6title:"Linux Debian",popup_image7:"PHPUnit is used to ensure code quality in the development of ETL processes. With Laravel Sail, a Docker-based local development environment, it is easy to set up and execute unit tests consistently and in isolation. This ensures that each component of the ETL functions as expected before being integrated into the main pipeline.",popup_image7title:"PHPUnit with Sail",popup_image8:"Atlassian is used for managing the ETL project, allowing tracking of tasks, developments, deadlines, and goals. Through its integration with tools like Jira and Confluence, Atlassian facilitates seamless collaboration among teams, ensuring that each step of the ETL process is well documented, tracked, and completed on time.",popup_image8title:"Atlassian (Project Management)",popup_image9:"Jira is used to track tasks and incidents related to the development of the ETL pipeline. Each step of the process, from extraction to transformation and loading, is managed and assigned in Jira, allowing for transparent tracking and effective priority management. Custom workflows help optimize processes, with sprints to manage development cycles.",popup_image9title:"Jira",popup_image10:"Confluence is used for documentation and collaboration around the ETL project. Every part of the process, from technical details to design decisions, is documented in Confluence, allowing the team to stay informed and up-to-date. This centralized platform also facilitates knowledge sharing and revision of critical information.",popup_image10title:"Confluence (Atlassian)",popup_image11:"The ETL methodology relies on Laravel to orchestrate the stages of extraction, transformation, and loading. Laravel simplifies the creation of modular and extensible ETL pipelines, with easy management of scheduled tasks and queues to process data in the background. Built-in features, like the Eloquent ORM, streamline the manipulation and transformation of data before loading it into a central warehouse.",popup_image11title:"ETL Methodology with Laravel",popup_image12:"The ETL project involves automating the extraction of data from various sources (CSV, SQL), transforming it through complex processes (cleaning, enrichment, feature generation), and then loading it into a centralized data warehouse. The ETL process aims to make data available for real-time analysis and visualization, ensuring data-driven decision-making based on reliable and up-to-date information.",popup_image12title:"General Summary of ETL",popup_image13:"A graphical dashboard from a related project is integrated to visualize movements and statistics, powered by the ETL and available data. With this tool, users can monitor each transaction, observe data flows (particularly transformations), identify anomalies or bottlenecks, and gain immediate insights into the transformed data.",popup_image13title:"Graphical Management Dashboard",popup_image14:"All projects related to the ETL are also designed as microservices, with each component of the pipeline decoupled and communicating via REST APIs. This ensures greater system flexibility, modularity, and scalability. Each microservice handles a part of the process (extraction, transformation, or loading) and can be deployed and updated independently while interacting smoothly with other components through standardized APIs.",popup_image14title:"Microservice with API",popup_image15:"JavaScript ES6 enhances client-side logic management by introducing modern features like classes, modules, promises, and shorthand syntax. For this project, ES6 facilitates DOM manipulation, user event handling, and asynchronous requests to the API. These features improve the fluidity and responsiveness of the user interface.",popup_image15title:"JavaScript ES6 (ECMAScript 6)",popup_image16:"jQuery simplifies interactions with the DOM, animation management, AJAX requests, and event manipulation. Although ES6 offers native alternatives, jQuery is still useful for ensuring compatibility with older browsers and simplifying some complex tasks. In this project, jQuery can be used to manage interactive components quickly and efficiently.",popup_image16title:"jQuery",popup_image17:"Webpack is a module bundler that simplifies dependency management and compiles JavaScript, CSS, images, and other resources in the project. For a SaaS application, Webpack can be used to optimize performance by creating compressed file bundles and dynamically loading the necessary components, improving application load time.",popup_image17title:"Webpack",popup_image18:"Metronic 8 is an administration dashboard based on Bootstrap, designed to be easily integrated into web applications. In this project, Metronic 8 allows for the creation of a clean and modern user interface for users of the SaaS application, with ready-to-use components for graphs, forms, and statistical dashboards.",popup_image18title:"Metronic 8 Dashboard",popup_image19:"PHP 8 provides significant performance improvements through its JIT (Just-In-Time) compiler. Within the project, PHP 8 optimizes backend operations for data management and processing, particularly for data collection and statistical analysis tasks. Additionally, new features like Union Types, Named Arguments, and Attributes allow for more flexible and readable code writing.",popup_image19title:"PHP Version 8",popup_image20:"SSH (Secure Shell) is a protocol that allows secure remote management of servers. In this project, SSH is used for deployment, management, and maintenance of the application on the server, ensuring the security of connections and data transfers during updates or configurations.",popup_image20title:"SSH Server",popup_image21:"SCRUM is an Agile methodology used for managing complex projects, particularly in software development. In the context of optimizing a SaaS application, SCRUM helps structure and organize work in small iterations called sprints, allowing for the rapid delivery of usable features and regular feedback from users or stakeholders. SCRUM promotes collaboration among teams, ensures continuous adaptation to changes, and improves the quality of the final product.",popup_image21title:"SCRUM",popup_image22:"Laravel is a PHP framework used for backend processing of the project. It offers an MVC architecture that facilitates the rapid development of robust web applications. For this project, Laravel allows for structuring API requests, managing databases, and implementing validation systems, while integrating features like notifications, queues, and user management.",popup_image22title:"Backend Processing with Laravel",popup_image23:"Jetstream and Breeze provide authentication options, with roles and permissions managed through policies. CSRF protection is enabled, data is strictly validated, and passwords are encrypted with bcrypt. Files are stored securely, sensitive data is encrypted, and XSS attacks are prevented by escaping data in views. User actions are audited, with login attempt limits to prevent brute-force attacks.",popup_image23title:"Laravel Security",popup_image24:"The code is modularly structured for a clear architecture. Migrations are used for the database, and the scheduler automates tasks. Configurations are managed with .env files, while deployments are automated via CI/CD pipelines. PHPUnit is used for automated testing, and caches like Redis or Memcached optimize performance.",popup_image24title:"Laravel Management",popup_image25:"XML is used to create the user interface with layouts like ConstraintLayout. The application ensures optimal accessibility with content descriptions, following best accessibility practices. Visual consistency is maintained with XML styles and themes, and animations are added to enhance the interface.",popup_image25title:"Android Display with XML",popup_image26:"Orchid is a banking ERP used to manage customer accounts, transactions, loans, and credits. It includes risk management and compliance features. Used as a backend for a banking application, it exposes APIs for real-time data synchronization and is deployed on robust servers with databases like Oracle or MySQL.",popup_image26title:"Orchid System (Banking ERP)",popup_image27:"Java is a key language for Android development, supporting object-oriented programming and integration with the Android SDK. Threads are used for heavy tasks, and background services ensure app responsiveness even when inactive. System event management through BroadcastReceiver optimizes the user experience.",popup_image27title:"Java Language for Android",popup_image28:"WSO2 is an open-source API management solution that secures access and monitors performance. In a banking application, it acts as a gateway between the front end and the backend (Orchid ERP), managing authentication via OAuth2 or JWT. It allows API publishing and versioning, with monitoring tools for performance analysis and banking service security.",popup_image28title:"WSO2 API Manager",popup_image29title:"Symfony — Senior Backend",popup_image29:"Symfony is used as a robust backend framework in this Senior role. It ensures solid API architecture, complex entity management and integration with mapping and AI modules. Its maturity and decoupled components guarantee performance and scalability.",popup_image30title:"WebSocket & Mercure — Real Time",popup_image30:"The WebSocket protocol via Mercure is used to stream real-time mapping data. It enables persistent bidirectional communication between server and clients, ensuring instant map updates without polling.",popup_image31title:"Symfony & REST API — Booking Platform",popup_image31:"Symfony with API Platform serves as a secure RESTful backend for the booking platform. It handles complex business logic: vehicle availability, booking statuses, payment integration and automatic confirmation generation.",popup_image32title:"Symfony 7 — Mentoring & Architecture",popup_image32:"Symfony 7 is at the core of mentored projects, providing a structured framework for teaching modern architecture. It illustrates DDD, CQRS and AI integration concepts directly within a proven professional framework.",popup_image33title:"Docker — Reproducible Environments",popup_image33:"Docker is used to create reproducible development environments, ideal for teaching and integrating local AI models (Ollama). Each stack (Symfony, Redis, Mercure, AI) is containerized, enabling instant deployment and complete isolation.",popup_image34title:"Next.js — SSR & App Router",popup_image34:"Next.js is the reference React framework used in the Senior role for full-stack interfaces. It enables server-side rendering (SSR), static generation (SSG) and App Router for a modular architecture, ensuring top performance and SEO.",popup_image35title:"React — Components & State",popup_image35:"React is used to build the UI with reusable components. Advanced state management (Context API, custom hooks) drives real-time map data and complex user interactions.",popup_image36title:"TypeScript — Static Typing",popup_image36:"TypeScript brings strict static typing to the entire codebase, catching errors at compile time. In this Senior role, it ensures code maintainability, simplifies code reviews and guarantees robust interfaces between modules.",popup_image37title:"Claude AI — AI Integration",popup_image37:"Anthropic Claude AI is integrated to enhance business modules: summary generation, decision support and complex task automation. The Claude API is consumed server-side via Symfony, ensuring security and request control.",popup_image38title:"Mercure — Real-Time Push",popup_image38:"The Mercure protocol (SSE-based) is used to stream real-time map events and business notifications. It replaces inefficient polling with native server push, integrated natively with Symfony.",popup_image39title:"Next.js — Booking Interface",popup_image39:"Next.js structures the booking interface with App Router, providing smooth navigation, hybrid SSR/CSR rendering and automatic image optimization for ultra-fast loading.",popup_image40title:"React — Dynamic UX",popup_image40:"React powers dynamic vehicle filtering, real-time availability display and the booking flow management, with optimized local state for fast user interactions.",popup_image41title:"REST API — API Platform",popup_image41:"API Platform (on Symfony) auto-generates documented RESTful endpoints. It handles vehicle, booking and payment resources with built-in validation, serialization and JWT security.",popup_image42title:"SEO — Visibility & Performance",popup_image42:"SEO is optimized via Next.js: dynamic metadata, automatic sitemap, SSR rendering for Google indexing and Core Web Vitals optimization. Result: better visibility and more organic traffic.",popup_image43title:"React — Mentored Projects",popup_image43:"React is the core technology taught during mentoring. Junior developers learn functional components, hooks (useState, useEffect, useContext) and professional patterns through real-world projects.",popup_image44title:"Tailwind CSS — Utility-First Design",popup_image44:"Tailwind CSS is used to build modern interfaces quickly with utility classes. It is taught as an alternative to Bootstrap, encouraging consistent design without unnecessary custom CSS.",popup_image45title:"Mercure — Real-Time Mentoring",popup_image45:"The Mercure protocol is integrated in mentored projects to introduce teams to real-time concepts, illustrating how to replace polling with server push in a Symfony architecture.",popup_image46title:"Claude AI — Local AI Solutions",popup_image46:"Local AI solutions based on Ollama (LLaMA, Mistral) and the Claude API are integrated in projects, automating code generation, testing and technical assistance without cloud dependency.",popup_image47title:"shadcn/ui — Modern UI Components",popup_image47:"shadcn/ui is used in the Senior role to accelerate the construction of professional interfaces with accessible, customizable and non-bundled components. It integrates natively with Next.js, Tailwind CSS and TypeScript, ensuring visual consistency and design system maintainability.",popup_image48title:"PMO — Project Management",popup_image48:"As PMO (Project Management Officer), I coordinate the full project lifecycle: scoping, planning, roadmap tracking, risk management and production delivery. I act as the strategic interface between technical teams and business stakeholders, ensuring goal alignment and on-time delivery.",popup_image49title:"shadcn/ui — Booking Interface",popup_image49:"shadcn/ui was used to rapidly build the booking platform interface: multi-step forms, modals, date pickers and dashboards. Its native compatibility with Next.js and Tailwind enabled smooth development and polished rendering.",popup_image50title:"Leaflet — Interactive Maps",popup_image50:"Leaflet (via React-Leaflet) is AGREETECH's mapping engine. It displays agricultural zones, manages geospatial data layers and integrates with Leaflet Draw for interactive drawing of polygons, rectangles and markers directly on the map.",popup_image51title:"Google Earth Engine — Satellite Imagery",popup_image51:"Google Earth Engine is used for large-scale satellite imagery analysis. It enables querying vegetation indices (NDVI), land use analysis, climate change detection and extraction of environmental indicators on drawn agricultural zones.",popup_image52title:"Turf.js — Geospatial Calculations",popup_image52:"Turf.js handles all client-side geospatial calculations: area and perimeter of drawn zones, centroid determination, GeoJSON geometry validation, intersections and buffers. Client-side execution ensures instant response without server calls.",popup_image53title:"React 19 — Agentic Interface",popup_image53:"React 19 with its new features (Server Components, Actions, use()) structures AGREETECH's interface. Geospatial components (map, analysis panels, visualizations) are built modularly and reactively for fluidity and maintainability.",popup_image54title:"TypeScript 5.8 — Typed Geometries",popup_image54:"TypeScript 5.8 types all geospatial structures: GeoJSON interfaces (Feature, FeatureCollection, Geometry), Redux types and REST API. Strict typing prevents errors on coordinates and ensures geographic data integrity throughout the pipeline.",popup_image55title:"Redux Toolkit — App State",popup_image55:"Redux Toolkit manages AGREETECH's global state: drawn zones, analysis results, map state, filters and navigation. Structured slices and immutability ensure predictable management of complex geospatial data.",popup_image56title:"React Query — Server Data",popup_image56:"TanStack React Query synchronizes data between the frontend and REST API with smart caching, automatic re-fetching and loading/error state management. It optimizes requests to the GeoJSON API and Google Earth Engine.",popup_image57title:"Material-UI — Design System",popup_image57:"Material-UI (MUI v7) with Emotion provides AGREETECH's complete design system: analysis panels, configuration forms, map drawers and dashboards. Its custom theme ensures professional visual consistency.",popup_image58title:"Vite — Ultra-Fast Build",popup_image58:"Vite 7 provides instant dev server startup and optimized production builds for AGREETECH. Its ultra-fast HMR (Hot Module Replacement) accelerates the development cycle of complex mapping components.",popup_image59title:"Chart.js — Environmental Visualization",popup_image59:"Chart.js (via react-chartjs-2) visualizes extracted environmental data: temporal NDVI charts, land use histograms, climate curves and agricultural indicators, synchronized with zones selected on the map.",authentification_securisee:"Secure Authentication",integration_paiement:"Payment Integration",cms_sur_mesure:"Custom CMS",optimisation_bdd:"Database Optimization",frontend:"Frontend",interfaces_modernes_reactives:"Modern and Reactive Interfaces",applications_spa:"SPA Applications",ui_ux_responsive:"Responsive UI/UX",animations_fluides:"Smooth Animations",dashboards_interactifs:"Interactive Dashboards",performance_optimisee:"Optimized Performance",specialises:"Specialized",solutions_techniques_sur_mesure:"Custom Technical Solutions",ecommerce_avance:"Advanced E-commerce",systemes_de_reservation:"Booking Systems",applications_metier:"Business Applications",automatisation:"Automation",seo_technique:"Technical SEO",maintenance:"Maintenance",support_optimisation_continue:"Continuous Support and Optimization",maintenance_preventive:"Preventive Maintenance",securite_renforcee:"Enhanced Security",performance_optimale:"Optimal Performance",support_reactif:"Reactive Support",monitoring_24_7:"24/7 Monitoring",conseil:"Consulting",expertise_technique_strategique:"Technical and Strategic Expertise",audit_approfondi:"In-depth Audit",architecture_systeme:"System Architecture",securite_avancee:"Advanced Security",analyse_strategique:"Strategic Analysis",formation_equipe:"Team Training",autres_services:"Other Services",services_devops:"DevOps Services",services_tests_qualite:"Quality Testing Services",services_r_d_technologique:"Technological R&D Services",accompagnement_croissance_digitale:"Digital Growth Support",what_i_offer:"What I offer",mes_services:"My Services",solutions_cloud:"Cloud Solutions",backend:"Backend",architecture_robuste_apis_performantes:"Robust Architecture and High-Performance APIs",apis_restful:"RESTful APIs","publish-date1":"November 15, 2021","publish-date2":"April 11, 2022","publish-date3":"May 23, 2022","publish-date4":"May 8, 2023","publish-date5":"June 21, 2023","publish-date6":"August 14, 2023","publish-date7":"June 30, 2024"},de:{home:"Startseite.",about:"Über.",skills:"Fähigkeiten.",portfolio:"Portfolio.",contact:"Kontakt.",yo:"Hallo!",presentation:"Mein Name ist Danih Stephane",engineer:"Ingenieur",developer:"Entwickler",coder:"Programmierer",get_in_touch:"Kontakt aufnehmen",years_of_experience:"Jahre Erfahrung",completed_projects:"Abgeschlossene Projekte",happy_clients:"Zufriedene Kunden",about_me:"Über mich",title_introduction:"Innovative Anwendungslösung? Lassen Sie uns Ihre Ideen verwirklichen!",introduction:"Hallo 👨‍💻, ich bin Danih Stéphane Rakotoarison Harilanto, ein erfahrener Anwendungsentwickler. Begeistert von Informationstechnologie, habe ich an verschiedenen Projekten gearbeitet, einschließlich SaaS-Lösungen und Cloud-Diensten. Meine Expertise umfasst Full-Stack-Entwicklung und die Zusammenarbeit mit Kreativteams, um Ideen in konkrete Lösungen zu verwandeln. Ob allein oder im Team, konzentriere ich mich auf effektives Projektmanagement, Agilität und offene Kommunikation, um den Erfolg sicherzustellen.",hire_me:"Stellen Sie mich ein",download_cv:"Lebenslauf herunterladen",my_skills:"Meine Fähigkeiten",title_skills:"Welche Bereiche umfassen meine technischen Fähigkeiten in der Entwicklung?",skills_desc:"Hier sind die technischen Fähigkeiten und Entwicklungstools, die es mir ermöglichen, Konzepte in funktionale und intuitive Webanwendungen zu verwandeln, indem ich die Beherrschung von Programmiersprachen, modernen Frameworks und optimierten Entwicklungsumgebungen kombiniere.",skills_button:"Fähigkeiten",tools_button:"Werkzeuge",my_experiences:"Beruflich",experience_title:"Über 3 Jahre Erfahrung in der Branche mit starkem Engagement in persönlichen Projekten",experience_introduction:"Ich hatte die Möglichkeit, an verschiedenen Projekten zu arbeiten, hauptsächlich im Bereich von SaaS-Lösungen und Cloud-Diensten. Während dieser Erfahrungen war ich an verschiedenen Aufgaben und Verantwortlichkeiten beteiligt, von der Entwicklung spezifischer Funktionen bis zur Optimierung der Systemarchitektur. Diese Eintauchen ermöglichte es mir, ein solides Verständnis der technischen Herausforderungen und Best Practices zu gewinnen, die mit diesen dynamischen Umgebungen verbunden sind.",june_2023_present:"Juni 2023 - Gegenwart 2024",first_box_title:"Datenmanagement mit ETL",first_box_description:"Extraktion: \n Integration verschiedener Daten (CSV, SQL). \n Geplante und regelmäßige Datenextraktion. \n Vorverarbeitung zur Korrektur und Normalisierung von Formaten. \n \n Transformation: \n Anwendung komplexer Transformationen über Pipelines. \n Datenbereinigung und -anreicherung. \n Erstellung neuer Funktionen aus Rohdaten. \n \n Laden: \n Speicherung der Daten in einem zentralen Lager. \n Verfügbarkeit der Daten zur Analyse und Visualisierung.",techno:"Entwicklungsekosystem",june_2022_june_2023:"Juni 2022 - Juni 2023",second_box_title:"Optimierung einer SaaS",second_box_description:"Verbesserung der Webanwendung zur Datenverwaltung, um die Effizienz und Genauigkeit der statistischen Erhebung zu steigern. Dieses Projekt zielt darauf ab, erweiterte Funktionen zu integrieren, um die Dateneingabe, -verarbeitung und -analyse zu erleichtern, während eine intuitive und benutzerfreundliche Oberfläche gewährleistet wird.",specifications:"Spezifikationen",specifications_descriptions:"Projektmanagement für Erhebung: Datenbank, Schnittstelle mit dem Kundensystem, Scheckbearbeitung, Marketing-Zielgruppe und Datenvisualisierung.",feb_2022_mai_2022:"Februar 2022 - Mai 2022",third_box_title:"Überarbeitung einer Dateneingabeschnittstelle",third_box_description:"Korrektur und Verbesserung eines Dateneingabetools, einschließlich erweiterter Validierungen, der Möglichkeit, Dateien zu importieren, exportierte verarbeitete Daten und Benutzerverwaltung mit Zugriffsrechten.",technical:"Technische Referenzen",aug_2021_des_2021:"August 2021 - Dezember 2021",fourth_box_title:"Java-Entwickler",fourth_box_description:"Mobile Banking, native Android-Anwendung, verbessert die Zugänglichkeit und den Komfort von Bankdienstleistungen und ermöglicht es den Benutzern, ihre Finanzen jederzeit und überall zu verwalten.",characteristics:"Eigenschaften",nov_2024_jan_2025:"Nov. 2024 - Jan. 2025",seventh_box_title:"KI-Entwickler & Mentor",seventh_box_role:"Technisches Mentoring & KI-Integration",seventh_box_description:"KI-Entwickler und technischer Mentor für React- und Symfony-Lösungen. Team-Coaching, Integration lokaler KI-Lösungen (Ollama), skalierbare Architektur mit Docker und Mercure für Echtzeit-Funktionen und Einführung von Entwicklungs-Best-Practices.",jan_2025_jun_2025:"Jan. 2025 - Jun. 2025",sixth_box_title:"Neugestaltung einer Fahrzeugbuchungsplattform",sixth_box_role:"Fullstack-Architekt & Performance",sixth_box_description:"Vollständige Neugestaltung einer Fahrzeugvermietungsplattform: ultrareaktives Next.js/React-Interface, sicheres Symfony-Backend, intelligente Fahrzeugfilterung, Mobile-Banking-Zahlungen, maßgeschneidertes Back-Office-Dashboard und SEO-Optimierung.",nov_2025_present:"Nov. 2025 - Heute",eighth_box_title:"Agentische KI & Geodatenanalyse",eighth_box_role:"AGREETECH-Projekt",eighth_box_description:"Entwicklung einer agentischen Geodatenanalyse-Plattform im Rahmen des AGREETECH-Projekts. Module für interaktives Zeichnen landwirtschaftlicher Zonen auf der Karte, Satellitenbildanalyse via Google Earth Engine, erweiterte räumliche Berechnungen mit Turf.js und Datenvisualisierung mit Chart.js. React 19 + TypeScript, Redux Toolkit, React Query, Material-UI und Vite.",jul_2025_present:"Jul. 2025 - Heute",fifth_box_title:"Lead Technisch & PMO — KI und Echtzeit-Kartierung",fifth_box_role:"Lead Technisch & PMO KI",fifth_box_description:"Nach einer anspruchsvollen internen Beurteilung zum Senior-Entwickler ernannt. Als Lead Technical und PMO leitete ich kritische Module mit Echtzeit-Kartierung und KI, führte Code-Reviews durch, koordinierte den gesamten Projektzyklus und fungierte als strategische Schnittstelle zwischen technischen Teams und Geschäftsleitungen.",my_education:"Mein Hintergrund",education_title:"Wie kann ein Bildungsweg zu technischer Exzellenz führen?",education_description:"Während meines Bildungsweges in der Informatik hatte ich die Gelegenheit, einen Masterabschluss an einer der besten Universitäten Europas zu erwerben, wo ich meine theoretischen und praktischen Kenntnisse vertiefte. Diese Erfahrung ermöglichte es mir, meine Anwendungsentwicklungsfähigkeiten zu stärken, während ich von einer soliden Informatikausbildung an lokalen Universitäten profitierte. Gleichzeitig erwarb ich eine strenge Grundlage in Mathematik, die für die Lösung komplexer Probleme und die Optimierung von Algorithmen unerlässlich ist, und bereitete mich darauf vor, die technischen Herausforderungen der Branche zu meistern.",education_first_box_title:"Universität Côte d'Azur",education_first_box_description:"Ingenieurwesen. Schwerpunkt Mobilität, Big Data und Systemintegration (MBDS)",license:"Lizenz",education_second_box_title:"IT-Universität",education_second_box_descirption:"Bachelor-Abschluss in Informationstechnologie. Spezialisierung auf Anwendungsentwicklung oder Programmierung.",academic:"Akademisch",education_third_box_title:"Fakultät für Mathematik",education_third_box_description:"Analyse, Algebra, Geometrie, Wahrscheinlichkeit und Statistik, Logik, Beweis, sowie Vektor- und Matrizenrechnung.",intensive_courses:"Intensivkurse",languages:"Sprachen",malagasy:"Malagasy (MG)",french:"Französisch (FR)",french_desc:"/ 2. Muttersprache",english:"Englisch (EN)",english_desc:"Berufliche Kenntnisse",german:"Deutsch (DE)",german_desc:"Anfänger",my_works:"Meine Arbeiten",my_works_title:"Innovative Lösungen, die Erwartungen übertreffen: Meine Projekte",my_works_introduction:"Entwerfen von außergewöhnlichen Websites, die Funktionalität und Ästhetik verbinden und eine langfristige Benutzerfreundlichkeit gewährleisten. Entwickeln einer sorgfältig gestalteten, klaren und gut dokumentierten Schnittstelle, die reibungslose und intuitive Interaktionen ermöglicht. Das Ziel ist es, elegante Lösungen zu schaffen, die den aktuellen Anforderungen der Kunden gerecht werden und sie auf die Zukunft vorbereiten.",load_more_work:"Mehr Arbeiten laden",recommandation_title:"Neugierig, was meine Kollegen über mich sagen? Hier sind ihre Gedanken!",recommandation_introduction:"Da ich nach neuen beruflichen Möglichkeiten suche, möchte ich Ihnen die Empfehlungen meiner Kollegen und Mentoren mitteilen. Ihr Feedback spiegelt meine Fähigkeiten, meine Arbeitsmoral und meine Fähigkeit wider, effektiv im Team zu arbeiten. Jede Empfehlung hebt eine einzigartige Erfahrung hervor und zeigt die Qualitäten, die mich zu einem idealen Kandidaten für eine Entwicklerposition machen.",recommandation_conclusion:"Sie können Empfehlungen auf LinkedIn hinzufügen",contact_title:"Haben Sie eine Idee oder ein Projekt? Lassen Sie mir gerne eine Nachricht zukommen!",contact_desc:"Für jegliche Unterstützung zögern Sie nicht, mich zu kontaktieren und mir mitzuteilen, wie ich Ihnen helfen kann. Füllen Sie das Formular aus, und ich werde Ihnen so schnell wie möglich antworten.",address:"Adresse:",phone:"Telefon:",phone_form:"Telefon (optional)",name:"Name",ex_name:"z.B. John Doe",ex_email:"z.B. john.doe@gmail.com",optional:"Telefonnummer",write_a_message:"Eine Nachricht schreiben",send:"Senden",proundly:"Mit Leidenschaft gestaltet, angetrieben von Innovation",recommandation_name1:"Diary Razafinjatovo · 1.",recommandation_post1:"Projektleiter / Certified Product Owner | Scrum Master",recommandation_date1:"Veröffentlicht am: 24. September 2024",recommandation_function1:"Diary war Danih Stephanes direkter Manager",recommandation_desc1:"Ich hatte das Vergnügen, mit Danih als sein Manager zusammenzuarbeiten, und ich kann bestätigen, dass er ein außergewöhnlicher Profi ist. Leidenschaftlich und stets auf der Suche nach Innovationen, brachte er ständig kreative Lösungen für jedes Projekt ein, an dem er beteiligt war. \n Er zeichnet sich durch seine Ernsthaftigkeit, sein Engagement und seine Fähigkeit aus, die Bedürfnisse des Projekts vorauszusehen und gleichzeitig innovative Ideen vorzuschlagen. Ob es darum ging, komplexe Probleme zu lösen oder die Entwicklungsprozesse zu optimieren, er fand immer effektive Lösungen. \n Seine Leidenschaft für die Entwicklung und sein Auge fürs Detail machen ihn zu einem wertvollen Mitglied in jedem Team. \n Ich empfehle ihn wärmstens.",recommandation_name2:"ZAFIMANANGA Josio Rigonolde · 1.",recommandation_post2:"PHP-Entwickler (Symfony, WordPress, ...) / ReactJs",recommandation_date2:"Veröffentlicht am: 23. September 2024",recommandation_function2:"ZAFIMANANGA arbeitete mit Danih Stephane im selben Team",recommandation_desc2:"Ich hatte das Vergnügen, eng mit Danih zusammenzuarbeiten, der bei jeder ihm übertragenen Aufgabe Durchhaltevermögen bewiesen hat. Selbst angesichts von Herausforderungen zeigte er große Entschlossenheit. \n Innerhalb unseres Teams bei eTech passte er sich schnell an die bestehenden Prozesse und Entwicklungstools an. Seine Fähigkeit, sich leicht in ein sich ständig wandelndes Umfeld zu integrieren, ist eine wertvolle Eigenschaft, die es ihm ermöglicht, effektiv zu kollektiven Projekten beizutragen. \n Danih fand dank seines hervorragenden Teamgeistes schnell seinen Platz in unserem Team. Immer bereit zur Zusammenarbeit und zum Austausch von Ideen, brachte er eine positive Energie ein, die die Gruppendynamik stärkte. \n Er ist ständig bestrebt, seine Fähigkeiten zu verbessern, was es ihm ermöglicht, schnell voranzukommen und bedeutende Beiträge zu jedem Projekt zu leisten.",recommandation_name3:"Njaratiana Herivola RAZAFINDRABE · 1.",recommandation_post3:"Tech Lead (PHP/Symfony/Laravel) | Scrum Master | Product Owner",recommandation_date3:"Veröffentlicht am: 20. September 2024",recommandation_function3:"Njaratiana Herivola war Danih Stephanes direkter Manager",recommandation_desc3:"Danih ist ein leidenschaftlicher Entwickler, sehr reaktionsschnell und proaktiv zugleich. Er kommuniziert sowohl gut mit dem Team als auch mit unseren Kunden. Er ist auch ein guter Mentor für die Praktikanten, die im Team gearbeitet haben. Meistens überrascht er uns mit zusätzlichen Projekten, die seine Leidenschaft für KI unterstreichen. Ich empfehle ihn nachdrücklich. Er wird ein großartiger Lead-Entwickler sein ;)",recommandation_name4:"Onintsoa Randriamiarinamanana · 1.",recommandation_post4:"IT-Entwickler",recommandation_date4:"Veröffentlicht am: 19. September 2024",recommandation_function4:"Onintsoa arbeitete mit Danih Stephane im selben Team",recommandation_desc4:"Ich hatte die Gelegenheit, mit Danih an mehreren Projekten zusammenzuarbeiten, und seine Programmierfähigkeiten sind bemerkenswert. Sein Code ist sauber und optimiert. Er ist ein kompetenter Entwickler, und ich empfehle Danih sehr.",recommandation_name5:"Philibert Hemmy Ramananjato · 1.",recommandation_post5:"Software-Entwicklungsingenieur",recommandation_date5:"Veröffentlicht am: 19. September 2024",recommandation_function5:"Philibert Hemmy und Danih Stephane besuchten dieselbe Schule",recommandation_desc5:"Er ist ein ausgezeichneter Teamkollege, immer bestrebt, seine Verpflichtungen zu erfüllen, und bereit zu helfen, wenn es nötig ist. Wir haben oft im selben Team zusammengearbeitet. Er ist ein engagierter Freiwilliger, der seine Verantwortung sehr ernst nimmt. Er ist geduldig und stets zuverlässig. Er hat auch einen großartigen Sinn für Humor, was eine echte Erleichterung ist, besonders wenn die Dinge nicht wie geplant laufen.",recommandation_name6:"Masinavalona EMIR TOLOJANAHARY · 1.",recommandation_post6:"PHP/Javascript-Entwickler",recommandation_date6:"Veröffentlicht am: 1. Oktober 2024",recommandation_function6:"Masinavalona EMIR arbeitete mit Danih Stephane im selben Team",recommandation_desc6:"Danih hat sich schnell in unser Projektteam bei eTech integriert und unsere Prozesse und Tools mit Leichtigkeit übernommen. Er ist immer aufmerksam und zeigt eine große Flexibilität, um sich an die Bedürfnisse des Teams anzupassen. Sein Durchhaltevermögen angesichts von Herausforderungen und sein ständiges Engagement sind beeindruckend, was ihn zu einem zuverlässigen Mitarbeiter und einem wertvollen Mitglied macht. \n Mit einem ausgezeichneten Teamgeist bringt Danih eine positive Energie ein, die die Dynamik der Gruppe stärkt. \n Eine seiner jüngsten Initiativen war es, sich für die Entwicklung der künstlichen Intelligenz zu interessieren und sie mühelos in die täglichen Aufgaben eines Entwicklers zu integrieren, wodurch unsere Effizienz optimiert wurde. \n Seine Neugier und sein Lernwille ermöglichen es ihm, schnell voranzukommen und bedeutende Beiträge zu jedem Projekt zu leisten. \n Ich empfehle ihn wärmstens.",popup_image1:"PHP 8 wird verwendet, um die Automatisierung von ETL-Prozessen zu orchestrieren, insbesondere zur Erleichterung der Extraktion, Transformation und des Ladens von Daten. Dank seiner neuen Funktionen wie dem JIT-Compiler und benannten Argumenten optimiert PHP 8 die Verarbeitung komplexer Daten und gewährleistet eine effiziente Verarbeitung. Typisierte Eigenschaften und strenge Fehlerbehandlung gewährleisten auch die Zuverlässigkeit und Robustheit von ETL-Skripten.",popup_image1title:"PHP 8 Technologie",popup_image2:"Laravel 8 wird als Grundlage verwendet, um ETL-Prozesse zu strukturieren und zu orchestrieren, und bietet eine robuste und gut organisierte Umgebung für die Extraktion, Transformation und das Laden von Daten. Mit seinen erweiterten Funktionen wie zeitgesteuerten Jobs (Scheduling), Warteschlangen zur Verwaltung von Hintergrundaufgaben und seinem leistungsstarken ORM Eloquent erleichtert Laravel die Verwaltung großer Datenmengen und gewährleistet eine effiziente und sichere Verarbeitung. Das Framework ermöglicht auch eine nahtlose Integration mit verschiedenen Speichersystemen und relationalen Datenbanken, während es dank seiner modularen und skalierbaren Architektur eine schnelle und wartbare Entwicklung ermöglicht.",popup_image2title:"Laravel 8 Technologie",popup_image3:"Docker wird verwendet, um alle ETL-Prozesse zu containerisieren, und bietet so eine isolierte und konsistente Umgebung für die Extraktion, Transformation und das Laden von Daten. Jede Komponente der ETL-Kette (Datenbank, Verarbeitungsskripte, Speicherung) ist in Containern gekapselt, was eine perfekte Portabilität und Reproduzierbarkeit zwischen Entwicklungs-, Test- und Produktionsumgebungen gewährleistet. Docker vereinfacht auch das Deployment und das Management von Abhängigkeiten, während es die Ressourcennutzung durch die Orchestrierung von Containern optimiert und somit eine reibungslose und skalierbare Ausführung des ETL-Pipelines gewährleistet.",popup_image3title:"Docker Technologie",popup_image4:"Jenkins wird verwendet, um das Deployment und die kontinuierliche Integration (CI/CD) im Rahmen des ETL-Projekts zu automatisieren. Mit seinen konfigurierbaren Pipelines ermöglicht Jenkins die Planung und Ausführung von Tests, Builds und Deployments, wodurch sichergestellt wird, dass die ETL-Prozesse systematisch getestet und in einer kontrollierten Umgebung bereitgestellt werden. Dies gewährleistet eine kontinuierliche und zuverlässige Bereitstellung von Funktionen mit schnellen Rückmeldungen zu möglichen Problemen.",popup_image4title:"Jenkins",popup_image5:"Bitbucket dient als Git-Plattform für die Versionsverwaltung und die Zusammenarbeit am Quellcode des ETL-Projekts. Funktionen wie Pull-Requests und Bitbucket CI-Pipelines ermöglichen es den Teams, Codeänderungen zu verfolgen und eine sichere und transparente Entwicklung zu gewährleisten. Bitbucket integriert sich auch mit anderen Tools im Ökosystem wie Jira und Confluence und erleichtert so ein effektives Projektmanagement.",popup_image5title:"Bitbucket",popup_image6:"Linux Debian ist das Betriebssystem, das für das Hosting der Infrastruktur des ETL-Projekts ausgewählt wurde. Bekannt für seine Stabilität, Sicherheit und große Kompatibilität mit Open-Source-Technologien bietet Debian eine zuverlässige Umgebung zum Ausführen von Docker-Containern, zur Orchestrierung von ETL-Prozessen und zur Verwaltung der erforderlichen Datenbanken und Dienste.",popup_image6title:"Linux Debian",popup_image7:"PHPUnit wird verwendet, um die Codequalität im Rahmen der Entwicklung von ETL-Prozessen sicherzustellen. Mit Laravel Sail, einer auf Docker basierenden lokalen Entwicklungsumgebung, ist es einfach, Unit-Tests konsistent und isoliert zu konfigurieren und auszuführen. Dies gewährleistet, dass jede Komponente des ETL wie vorgesehen funktioniert, bevor sie in die Hauptpipeline integriert wird.",popup_image7title:"PHPUnit mit Sail",popup_image8:"Atlassian wird für das Management des ETL-Projekts verwendet und ermöglicht das Verfolgen von Aufgaben, Entwicklungen, Fristen und Zielen. Dank der Integration mit Tools wie Jira und Confluence erleichtert Atlassian eine transparente Zusammenarbeit zwischen den Teams und stellt sicher, dass jeder Schritt des ETL-Prozesses gut dokumentiert, verfolgt und fristgerecht abgeschlossen wird.",popup_image8title:"Atlassian (Projektmanagement)",popup_image9:"Jira wird verwendet, um die Aufgaben und Vorfälle im Zusammenhang mit der Entwicklung der ETL-Pipeline zu verfolgen. Jeder Schritt des Prozesses, von der Extraktion über die Transformation bis hin zum Laden, wird in Jira verwaltet und zugewiesen, was eine transparente Nachverfolgung und ein effektives Prioritätenmanagement ermöglicht. Die benutzerdefinierten Workflows helfen dabei, die Prozesse zu optimieren, mit Sprints zur Verwaltung der Entwicklungszyklen.",popup_image9title:"Jira",popup_image10:"Confluence wird für die Dokumentation und die Zusammenarbeit rund um das ETL-Projekt verwendet. Jeder Teil des Prozesses, von technischen Details bis zu Entwurfsentscheidungen, wird in Confluence dokumentiert, sodass das Team informiert und auf dem neuesten Stand bleibt. Diese zentrale Plattform erleichtert auch den Wissensaustausch und die Überprüfung kritischer Informationen.",popup_image10title:"Confluence (Atlassian)",popup_image11title:"ETL-Methodologie mit Laravel",popup_image11:"Die ETL-Methodologie basiert auf Laravel, um die Schritte der Extraktion, Transformation und des Ladens zu orchestrieren. Laravel erleichtert die Erstellung modularer und erweiterbarer ETL-Pipelines, mit einer einfachen Verwaltung geplanter Aufgaben und Warteschlangen zur Verarbeitung von Daten im Hintergrund. Die integrierten Funktionen, wie das ORM Eloquent, vereinfachen die Manipulation und Transformation von Daten, bevor sie in ein zentrales Lager geladen werden.",popup_image12title:"Allgemeine Zusammenfassung des ETL",popup_image12:"Das ETL-Projekt besteht darin, die Extraktion von Daten aus verschiedenen Quellen (CSV, SQL) zu automatisieren, sie durch komplexe Prozesse (Bereinigung, Anreicherung, Generierung von Merkmalen) zu transformieren und sie dann in ein zentrales Data Warehouse zu laden. Der ETL-Prozess zielt darauf ab, Daten für Analysen und Echtzeitvisualisierungen verfügbar zu machen, um sicherzustellen, dass Entscheidungen auf zuverlässigen und aktuellen Daten basieren.",popup_image13title:"Grafisches Management-Dashboard",popup_image13:"Ein grafisches Dashboard aus einem verwandten Projekt ist integriert, um Bewegungen und Statistiken anzuzeigen, die vom ETL und den verfügbaren Daten gespeist werden. Mit diesem Tool können Benutzer jede Transaktion überwachen, Datenbewegungen (insbesondere Transformationen) beobachten, Anomalien oder Engpässe erkennen und sofortige Einblicke in die transformierten Daten erhalten.",popup_image14title:"Mikroservice mit API",popup_image14:"Alle ETL-bezogenen Projekte sind ebenfalls als Microservices konzipiert, wobei jede Komponente der Pipeline entkoppelt und über REST-APIs kommuniziert. Dies gewährleistet eine größere Flexibilität, Modularität und Skalierbarkeit des Systems. Jeder Microservice übernimmt einen Teil des Prozesses (Extraktion, Transformation oder Laden) und kann unabhängig bereitgestellt und aktualisiert werden, während er nahtlos mit den anderen Komponenten über standardisierte APIs interagiert.",popup_image15title:"JavaScript ES6 (ECMAScript 6)",popup_image15:"JavaScript ES6 verbessert die Verwaltung der Logik auf der Client-Seite, indem es moderne Funktionen wie Klassen, Module, Promises und Syntaxkürzungen einführt. Für dieses Projekt erleichtert ES6 die Manipulation des DOM, die Verwaltung von Benutzerevents und das Senden von asynchronen Anfragen an die API. Diese Funktionen verbessern die Fluidität und Reaktivität der Benutzeroberfläche.",popup_image16title:"jQuery",popup_image16:"jQuery vereinfacht die Interaktionen mit dem DOM, die Verwaltung von Animationen, AJAX-Anfragen und die Ereignisbehandlung. Obwohl ES6 native Alternativen bietet, ist jQuery nach wie vor nützlich, um die Kompatibilität mit älteren Browsern sicherzustellen und einige komplexe Aufgaben zu vereinfachen. In diesem Projekt kann jQuery verwendet werden, um interaktive Komponenten schnell und effizient zu verwalten.",popup_image17title:"Webpack",popup_image17:"Webpack ist ein Modul-Bundler, der die Verwaltung von Abhängigkeiten und die Kompilierung von JavaScript-, CSS-, Bild- und anderen Ressourcen im Projekt erleichtert. Für eine SaaS-Anwendung kann Webpack verwendet werden, um die Leistung zu optimieren, indem komprimierte Datei-Bundles erstellt und die erforderlichen Komponenten dynamisch geladen werden, was die Ladezeiten der Anwendung verbessert.",popup_image18title:"Metronic 8 Dashboard",popup_image18:"Metronic 8 ist ein auf Bootstrap basierendes Administrations-Dashboard, das für die einfache Integration in Webanwendungen konzipiert ist. In diesem Projekt ermöglicht Metronic 8 die Erstellung einer sauberen und modernen Benutzeroberfläche für die Benutzer der SaaS-Anwendung, mit sofort einsatzbereiten Komponenten für Grafiken, Formulare und statistische Dashboards.",popup_image19title:"PHP Version 8",popup_image19:"PHP 8 bietet signifikante Leistungsverbesserungen durch seinen JIT-Compiler (Just-In-Time). Im Rahmen des Projekts ermöglicht PHP 8 die Optimierung der Backend-Operationen zur Verwaltung und Verarbeitung von Daten, insbesondere für Aufgaben der Datensammlung und statistischen Analyse. Darüber hinaus ermöglichen neue Funktionen wie Union Types, Named Arguments und Attributes eine flexiblere und lesbarere Code-Schreibung.",popup_image20title:"SSH-Server",popup_image20:"SSH (Secure Shell) ist ein Protokoll, das die sichere Verwaltung von Servern aus der Ferne ermöglicht. In diesem Projekt wird SSH für das Deployment, die Verwaltung und die Wartung der Anwendung auf dem Server verwendet, um die Sicherheit der Verbindungen und Datenübertragungen während Updates oder Konfigurationen zu gewährleisten.",popup_image21title:"SCRUM",popup_image21:"SCRUM ist eine Agile-Methodik, die für die Verwaltung komplexer Projekte, insbesondere in der Softwareentwicklung, verwendet wird. Im Kontext der Optimierung einer SaaS-Anwendung ermöglicht SCRUM die Strukturierung und Organisation der Arbeit in kleinen Iterationen, sogenannten Sprints, was eine schnelle Bereitstellung von nutzbaren Funktionen und regelmäßiges Feedback von Benutzern oder Interessengruppen ermöglicht. SCRUM fördert die Zusammenarbeit zwischen den Teams, sorgt für eine kontinuierliche Anpassung an Veränderungen und verbessert die Qualität des Endprodukts.",popup_image22title:"Backend-Verarbeitung mit Laravel",popup_image22:"Laravel ist ein PHP-Framework, das für die Backend-Verarbeitung des Projekts verwendet wird. Es bietet eine MVC-Architektur, die die schnelle Entwicklung robuster Webanwendungen erleichtert. Für dieses Projekt ermöglicht Laravel die Strukturierung von API-Anfragen, die Verwaltung von Datenbanken und die Implementierung von Validierungssystemen, während Funktionen wie Benachrichtigungen, Warteschlangen und Benutzerverwaltung integriert werden.",popup_image23title:"Laravel-Sicherheit",popup_image23:"Jetstream und Breeze sind Authentifizierungsoptionen, die zusammen mit Rollen und Berechtigungen über Richtlinien konfiguriert sind. Der CSRF-Schutz ist aktiviert, Daten werden rigoros validiert, und Passwörter werden mit bcrypt verschlüsselt. Dateien werden sicher gespeichert, sensible Daten werden verschlüsselt, und ein Schutz vor XSS-Angriffen wird durch Escape-Sequenzen in den Ansichten gewährleistet. Ein Benutzeraktionsaudit ist implementiert, und eine Begrenzung der Anmeldeversuche verhindert Brute-Force-Angriffe.",popup_image24title:"Laravel-Verwaltung",popup_image24:"Der Code ist modular strukturiert für eine klare Architektur. Migrationen werden für die Datenbank verwendet und der Scheduler automatisiert Aufgaben. Konfigurationen werden über .env-Dateien verwaltet, während Deployments über CI/CD-Pipelines automatisiert werden. PHPUnit wird für automatisierte Tests verwendet, und Caches wie Redis oder Memcached optimieren die Leistung.",popup_image25title:"Android-Anzeige mit XML",popup_image25:"XML wird verwendet, um die Benutzeroberfläche mit Layouts wie ConstraintLayout zu erstellen. Die App gewährleistet optimale Barrierefreiheit durch Inhaltsbeschreibungen, die den besten Barrierefreiheitspraktiken folgen. Die visuelle Konsistenz wird durch XML-Stile und -Themen aufrechterhalten, und Animationen fügen der Benutzeroberfläche Dynamik hinzu.",popup_image26title:"Orchid-System (Bank-ERP)",popup_image26:"Orchid ist ein Bank-ERP zur Verwaltung von Kundenkonten, Transaktionen, Darlehen und Krediten. Es integriert Risikomanagement- und Compliance-Funktionen. Es wird als Backend für eine Banking-Anwendung verwendet, stellt APIs für die Echtzeit-Datensynchronisation bereit und wird auf robusten Servern mit Datenbanken wie Oracle oder MySQL eingesetzt.",popup_image27title:"JAVA-Sprache für Android",popup_image27:"Java ist eine Schlüsseltechnologie für die Android-Entwicklung, die objektorientierte Programmierung und die Integration mit dem Android-SDK unterstützt. Threads werden für schwere Aufgaben verwendet, und Hintergrunddienste gewährleisten die Reaktionsfähigkeit der App auch im Leerlauf. Das Ereignismanagement des Systems über BroadcastReceiver optimiert die Benutzererfahrung.",popup_image28title:"WSO2 API Manager",popup_image28:"WSO2 ist eine Open-Source-Lösung für das API-Management, die den Zugriff sichert und die Leistung überwacht. In einer Banking-Anwendung fungiert er als Gateway zwischen Frontend und Backend (Orchid-ERP) und verwaltet die Authentifizierung über OAuth2 oder JWT. Er ermöglicht die Veröffentlichung und Versionierung von APIs und bietet Überwachungstools, um die Leistung zu analysieren und Bankdienste zu sichern.",popup_image29title:"Symfony — Senior Backend",popup_image29:"Symfony wird als robustes Backend-Framework in dieser Senior-Rolle verwendet. Es gewährleistet eine solide API-Architektur, komplexe Entity-Verwaltung und Integration mit Kartierungs- und KI-Modulen.",popup_image30title:"WebSocket & Mercure — Echtzeit",popup_image30:"Das WebSocket-Protokoll über Mercure wird für das Echtzeit-Streaming von Kartierungsdaten verwendet. Es ermöglicht eine persistente bidirektionale Kommunikation zwischen Server und Clients ohne Polling.",popup_image31title:"Symfony & REST API — Buchungsplattform",popup_image31:"Symfony mit API Platform dient als sicheres RESTful-Backend für die Buchungsplattform und verwaltet Fahrzeugverfügbarkeit, Buchungsstatusänderungen und Zahlungsintegration.",popup_image32title:"Symfony 7 — Mentoring & Architektur",popup_image32:"Symfony 7 bildet das Herzstück der betreuten Projekte und bietet einen strukturierten Rahmen für die Vermittlung moderner Architektur, DDD und CQRS-Konzepte.",popup_image33title:"Docker — Reproduzierbare Umgebungen",popup_image33:"Docker wird verwendet, um reproduzierbare Entwicklungsumgebungen zu erstellen, ideal für die Integration lokaler KI-Modelle (Ollama). Jeder Stack ist containerisiert für sofortige Bereitstellung.",popup_image34title:"Next.js — SSR & App Router",popup_image34:"Next.js ist das bevorzugte React-Framework in der Senior-Rolle. Es ermöglicht serverseitiges Rendering, statische Generierung und App Router für eine modulare Architektur mit optimaler Performance.",popup_image35title:"React — Komponenten & State",popup_image35:"React wird für wiederverwendbare UI-Komponenten eingesetzt. Fortschrittliches State Management steuert Echtzeit-Kartendaten und komplexe Benutzerinteraktionen.",popup_image36title:"TypeScript — Statische Typisierung",popup_image36:"TypeScript bringt strikte statische Typisierung in die gesamte Codebasis, erkennt Fehler zur Kompilierzeit und gewährleistet Wartbarkeit und robuste Schnittstellen zwischen Modulen.",popup_image37title:"Claude AI — KI-Integration",popup_image37:"Anthropic Claude KI wird für Zusammenfassungen, Entscheidungsunterstützung und Automatisierung komplexer Aufgaben integriert. Die API wird serverseitig über Symfony konsumiert.",popup_image38title:"Mercure — Echtzeit-Push",popup_image38:"Das Mercure-Protokoll (SSE-basiert) streamt Echtzeit-Kartenereignisse und Benachrichtigungen, ersetzt ineffizientes Polling durch nativen Server-Push, nativ in Symfony integriert.",popup_image39title:"Next.js — Buchungsinterface",popup_image39:"Next.js strukturiert das Buchungsinterface mit App Router, flüssiger Navigation und hybridem SSR/CSR-Rendering für ultraschnelles Laden.",popup_image40title:"React — Dynamische UX",popup_image40:"React steuert die dynamische Fahrzeugfilterung, Echtzeit-Verfügbarkeitsanzeige und den Buchungsprozess mit optimiertem lokalem State.",popup_image41title:"REST API — API Platform",popup_image41:"API Platform auf Symfony generiert automatisch dokumentierte RESTful-Endpunkte mit eingebetteter Validierung, Serialisierung und JWT-Sicherheit.",popup_image42title:"SEO — Sichtbarkeit & Performance",popup_image42:"SEO wird über Next.js optimiert: dynamische Metadaten, automatische Sitemap, SSR für Google-Indexierung und Core Web Vitals-Optimierung.",popup_image43title:"React — Betreute Projekte",popup_image43:"React ist die zentrale Technologie im Mentoring. Junior-Entwickler lernen funktionale Komponenten, Hooks und professionelle Patterns in realen Projekten.",popup_image44title:"Tailwind CSS — Utility-First Design",popup_image44:"Tailwind CSS wird für schnelle, moderne Interfaces mit Utility-Klassen eingesetzt und als Bootstrap-Alternative mit konsistentem Design unterrichtet.",popup_image45title:"Mercure — Echtzeit im Mentoring",popup_image45:"Das Mercure-Protokoll wird in betreuten Projekten eingesetzt, um Teams in Echtzeit-Konzepten zu schulen und Server-Push in Symfony zu demonstrieren.",popup_image46title:"Claude AI — Lokale KI-Lösungen",popup_image46:"Lokale KI-Lösungen auf Ollama-Basis (LLaMA, Mistral) und die Claude API automatisieren Code-Generierung und technische Unterstützung ohne Cloud-Abhängigkeit.",popup_image47title:"shadcn/ui — Moderne UI-Komponenten",popup_image47:"shadcn/ui wird in der Senior-Rolle eingesetzt, um professionelle Interfaces mit zugänglichen, anpassbaren Komponenten schnell aufzubauen. Nativ kompatibel mit Next.js, Tailwind CSS und TypeScript.",popup_image48title:"PMO — Projektmanagement",popup_image48:"Als PMO koordiniere ich den vollständigen Projektlebenszyklus: Planung, Roadmap-Verfolgung, Risikomanagement und Produktionslieferung als strategische Schnittstelle zwischen technischen Teams und Geschäftsleitungen.",popup_image49title:"shadcn/ui — Buchungsinterface",popup_image49:"shadcn/ui wurde für den schnellen Aufbau der Buchungsplattform eingesetzt: mehrstufige Formulare, Modals, Datumsauswahl und Dashboards, nativ kompatibel mit Next.js und Tailwind.",popup_image50title:"Leaflet — Interaktive Karten",popup_image50:"Leaflet (via React-Leaflet) ist die Kartierungs-Engine von AGREETECH. Zeigt landwirtschaftliche Zonen an und integriert Leaflet Draw für interaktives Zeichnen von Polygonen und Markierungen.",popup_image51title:"Google Earth Engine — Satellitenbilder",popup_image51:"Google Earth Engine analysiert Satellitenbilder: NDVI-Indizes, Landnutzungsanalyse, Klimaänderungserkennung und Umweltindikatoren auf gezeichneten landwirtschaftlichen Zonen.",popup_image52title:"Turf.js — Geodatenberechnungen",popup_image52:"Turf.js führt clientseitige Geodatenberechnungen durch: Fläche, Umfang, Zentroid, GeoJSON-Validierung, Schnittmengen und Puffer — ohne Serveraufruf.",popup_image53title:"React 19 — Agentisches Interface",popup_image53:"React 19 strukturiert AGREETECH's Interface mit modularen Karten-, Analyse- und Visualisierungskomponenten für maximale Reaktivität und Wartbarkeit.",popup_image54title:"TypeScript 5.8 — Typisierte Geometrien",popup_image54:"TypeScript 5.8 typisiert GeoJSON-Strukturen, Redux und REST-API streng, verhindert Koordinatenfehler und sichert die Geodatenintegrität.",popup_image55title:"Redux Toolkit — App-Zustand",popup_image55:"Redux Toolkit verwaltet den globalen Zustand: Zonen, Analyseergebnisse, Kartenzustand und Filter mit strukturierten Slices und Unveränderlichkeit.",popup_image56title:"React Query — Serverdaten",popup_image56:"TanStack React Query synchronisiert Frontend und REST-API mit intelligentem Cache, automatischem Re-Fetching und Lade-/Fehlerzustandsverwaltung.",popup_image57title:"Material-UI — Design-System",popup_image57:"MUI v7 mit Emotion liefert das komplette Design-System: Analyse-Panels, Formulare, Karten-Drawer und Dashboards mit professionellem Custom-Theme.",popup_image58title:"Vite — Ultraschneller Build",popup_image58:"Vite 7 bietet sofortigen Dev-Server-Start und optimierte Produktions-Builds mit ultraschnellem HMR für komplexe Kartenkomponenten.",popup_image59title:"Chart.js — Umweltdatenvisualisierung",popup_image59:"Chart.js visualisiert Umweltdaten: zeitliche NDVI-Diagramme, Landnutzungshistogramme und Klimakurven, synchronisiert mit Kartenzonen.",authentification_securisee:"Gesicherte Authentifizierung",integration_paiement:"Zahlungsintegration",cms_sur_mesure:"Maßgeschneidertes CMS",optimisation_bdd:"Datenbankoptimierung",frontend:"Frontend",interfaces_modernes_reactives:"Moderne und reaktionsschnelle Schnittstellen",applications_spa:"SPA-Anwendungen",ui_ux_responsive:"Responsive UI/UX",animations_fluides:"Flüssige Animationen",dashboards_interactifs:"Interaktive Dashboards",performance_optimisee:"Optimierte Leistung",specialises:"Spezialisiert",solutions_techniques_sur_mesure:"Maßgeschneiderte technische Lösungen",ecommerce_avance:"Erweitertes E-Commerce",systemes_de_reservation:"Buchungssysteme",applications_metier:"Business-Anwendungen",automatisation:"Automatisierung",seo_technique:"Technisches SEO",maintenance:"Wartung",support_optimisation_continue:"Support und kontinuierliche Optimierung",maintenance_preventive:"Präventive Wartung",securite_renforcee:"Erhöhte Sicherheit",performance_optimale:"Optimale Leistung",support_reactif:"Reaktiver Support",monitoring_24_7:"24/7 Monitoring",conseil:"Beratung",expertise_technique_strategique:"Technisches und strategisches Fachwissen",audit_approfondi:"Tiefgehendes Audit",architecture_systeme:"Systemarchitektur",securite_avancee:"Erweiterte Sicherheit",analyse_strategique:"Strategische Analyse",formation_equipe:"Team-Schulung",autres_services:"Weitere Dienstleistungen",services_devops:"DevOps-Dienste",services_tests_qualite:"Tests und Qualitätsdienste",services_r_d_technologique:"Technologische F&E-Dienste",accompagnement_croissance_digitale:"Begleitung im digitalen Wachstum",what_i_offer:"Was ich anbiete",mes_services:"Meine Dienste",solutions_cloud:"Cloud-Lösungen",backend:"Backend",architecture_robuste_apis_performantes:"Robuste Architektur und Hochleistungs-APIs",apis_restful:"RESTful-APIs","publish-date1":"15. November 2021","publish-date2":"11. April 2022","publish-date3":"23. Mai 2022","publish-date4":"8. Mai 2023","publish-date5":"21. Juni 2023","publish-date6":"14. August 2023","publish-date7":"30. Juni 2024"},mg:{home:"Fandraisana.",about:"Mombamomba.",skills:"Fahaiza-manao.",portfolio:"Portfolio.",contact:"Hifandray.",yo:"Miarahaba!",presentation:"Danih Stephane no anarako",engineer:"Injeniera",developer:"Mpamorona rindrambaiko",coder:"Mpandika kaody",get_in_touch:"Hifandray amiko",years_of_experience:"Taonan'ny traikefa",completed_projects:"Tetikasa vita",happy_clients:"Mpanjifa faly",about_me:"Momba ahy",title_introduction:"Vahaolana amin'ny tetikasa vaovao ? Aleo fa ho ataontsika tanteraka izay eritreritrao!",introduction:"Salama 👨‍💻, Danih Stéphane Rakotoarison Harilanto no anarako, mpamorona rindrambaiko efa za-draharaha. Mahafinaritra ahy ny haitao fampahalalam-baovao amin'ny teknolojia, ary efa niasa tamin'ny tetikasa maro, anisan'izany ny vahaolana SaaS sy ny serivisy rahona (Cloud). Ny fahaizako dia mandrakotra ny fampivoarana feno ary ny fiaraha-miasa amin'ny ekipa famoronana mba hanova hevitra ho vahaolana azo tanterahina. Na miasa irery na ao anaty ekipa, mifantoka amin'ny fitantanana tetikasa mahomby, ny fahamatorana, ary ny fifandraisana misokatra mba hahazoana antoka ny fahombiazana.",hire_me:"Hiasa miaraka amiko",download_cv:"Hisintona ny taratasy Fiainan'asa",my_skills:"Ny fahaiza-manaoko",title_skills:"Inona avy ny faritra teknika amin'ny fahaiza-manaoko amin'ny fampivoarana?",skills_desc:"Ireto ary ny fahaiza-manao teknika sy fitaovana fampivoarana ahafahako manova hevitra ho lasa fampiharana tranonkala miasa tsara sy mora azo avy hatrany, miaraka amin'ny fahaiza-manaona programa, framework ankehitriny, ary tontolo teknolojia voaomana tsara.",skills_button:"Fahaiza-manao",tools_button:"Fitaovana",my_experiences:"Asa matihanina",experience_title:"Mihoatra ny 3 taona niainana teo amin'ny indostria miaraka amin'ny tetikasa manokana betsaka",experience_introduction:"Nahazo fahafahana niasa tamin'ny tetikasa maro aho, indrindra amin'ny sehatry ny vahaolana SaaS sy ny serivisy rahona (Cloud). Nandritra ireo traikefa ireo, nandray anjara tamin'ny asa sy andraikitra maro aho, manomboka amin'ny fampandrosoana endri-javatra manokana ka hatramin'ny fanatsarana ny rafitra. Izany traikefa izany dia nanome ahy fahatakarana matotra ny fanamby ara-teknika sy ny fomba fanao tsara indrindra mifandraika amin'ireo tontolo iainana mavitrika ireo.",june_2023_present:"Jona 2023 - Ankehitriny 2024",first_box_title:"Fitantanana Angona amin'ny ETL",first_box_description:"Fanangonana: \n Fampidirana angon-drakitra maro (CSV, SQL). \n Fanangonana angon-drakitra voalahatra sy matetika. \n Fanodinana mialoha, fanitsiana sy fanatsarana ny endrikin'ny angon-drakitra. \n \n Fanovana: \n Fampiharana fanovana sarotra amin'ny alalan'ny pipelines. \n Fanadiovana sy fampivoarana ny angona. \n Famoronana endri-javatra vaovao avy amin'ny angon-drakitra voalohany. \n \n Fanangonana: \n Fitahirizana ny angona ao amin'ny toerana voatokana sy vokarakara. \n Fisian'ny angon-drakitra ho an'ny famakafakana sy ny fijerena sary.",techno:"Tontolo teknolojia amin'ny fampandrosoana",june_2022_june_2023:"Jona 2022 - Jona 2023",second_box_title:"Fanatsarana SaaS",second_box_description:"Fanatsarana ny fampiharana tranonkala amin'ny fitantanana angona mba hampitomboana ny fahombiazan'ny fanangonana statistika sy ny fahamarinan'ny angona. Ity tetikasa ity dia mikendry ny hampiditra endri-javatra mandroso hanamora ny fidirana angona, ny fanodinana ary ny famakafakana raha miantoka ny fisian'ny endrika mora azo sy mora ampiasaina.",specifications:"Fepetra",specifications_descriptions:"Fitantanana tetikasa ho an'ny fanangonana: banky angon-drakitra, fifandraisana amin'ny ekosistemam-panjifa, fanodinana sheky, fitadiavana mpanjifa amin'ny varotra ary fijerena angon-drakitra amin'ny sary.",feb_2022_mai_2022:"Febroary 2022 - Mey 2022",third_box_title:"Fanamboarana ny Rafitra Fidirana Angona",third_box_description:"Fanamboarana sy fanatsarana ny fitaovana fidirana angon-drakitra, manampy fanamarinana mandroso, fahafahana mampiditra rakitra, fanondranana ny angona voahodina, ary fitantanana mpampiasa miaraka amin'ny zo fidirana.",technical:"Loharano ara-teknika",aug_2021_des_2021:"Aogositra 2021 - Desambra 2021",fourth_box_title:"Mpamorona rindrambaiko Java",fourth_box_description:"Mobile Banking, fampiasana Android ifotony, manatsara ny fahafahana miditra sy ny fahafahan'ny serivisy ara-bola, mamela ny mpampiasa hitantana ny volany na aiza na aiza ary amin'ny fotoana rehetra.",characteristics:"Toetra teknolojia",nov_2024_jan_2025:"Nov. 2024 - Jan. 2025",seventh_box_title:"Mpamorona IA & Mpanoro",seventh_box_role:"Fanofanana Teknika & Saidim-pifandraisana IA",seventh_box_description:"Mpamorona rindrambaiko IA sy Mpanoro Teknika amin'ny vahaolana React sy Symfony. Fampianarana ekipa, fampidirana vahaolana IA eo an-toerana (Ollama), rafitra scalable miaraka amin'ny Docker sy Mercure ary fampandehanana fomba fijery tsara indrindra.",jan_2025_jun_2025:"Jan. 2025 - Jun. 2025",sixth_box_title:"Fanavaozana Sehatra Fametahana Fiara",sixth_box_role:"Architecte Fullstack & Performance",sixth_box_description:"Fanavaozana tanteraka ny sehatra fametahana fiara: interface Next.js/React mahomby, Symfony backend voarindrina, filtrage maranitra, fandoavana mobile banking, dashboard back-office manokana ary fanatsarana SEO.",nov_2025_present:"Nov. 2025 - Ankehitriny",eighth_box_title:"Agentic AI & Famakafakana Jeospasialy",eighth_box_role:"Tetikasa AGREETECH",eighth_box_description:"Fampandrosoana sehatra famakafakana jeospasialy agentique amin'ny tetikasa AGREETECH. Modiolin'ny famoronana tanana ny faritra fambolena amin'ny sarintany, famakafakana sarin'ny satalaita amin'ny Google Earth Engine, kajy jeospasialy mandroso (velarana, sisiny, centroïde) amin'ny Turf.js ary fisehoana angon-drakitra amin'ny Chart.js. React 19 + TypeScript, Redux Toolkit, React Query, Material-UI ary Vite.",jul_2025_present:"Jul. 2025 - Ankehitriny",fifth_box_title:"Lead Teknika & PMO — AI sy Sarintany Fotoana Tena",fifth_box_role:"Lead Teknika & PMO IA",fifth_box_description:"Nofidin'ny mpiasa avo lenta taorian'ny fanombanana anatiny henjana. Amin'ny maha Lead Technique sy PMO, nitantana modiolin'asa manan-danja miantanana amin'ny sarintany sy AI aho, nitondra ny fandinihana code, nandrindra ny dingana feno ny tetikasa ary nisolo tena ny mpandraharaha teknika sy ny fitantanana.",my_education:"Ny fianarako",education_title:"Ahoana no ahafahan'ny fianarana mitondra ho amin'ny zava-bita amin'ny teknolojia?",education_description:"Nandritra ny lalamianarako amin'ny fampandrosoana informatika, nahazo fahafahana nahazona mari-pahaizana master tao amin'ny iray amin'ireo oniversite tsara indrindra tao Eoropa aho, izay nianarako lalina ny fahaiza-manao ara-teorika sy ara-pratika. Ity traikefa ity dia nanampy ahy hanatsara ny fahaiza-manao rindrambaiko, nampihatra sy nankafy ny fanabeazana informatika matanjaka nentin'ny oniversite teo an-toerana. Mandritra izany fotoana izany, nahazo fototra mafy amin'ny matematika aho, izay ilaina amin'ny famahana olana sarotra sy ny fanatsarana ny algoritma, ka nanomana ahy hiatrika ny fanamby ara-teknika ao amin'ny indostria.",education_first_box_title:"Oniversiten'i Côte d'Azur",education_first_box_description:"Injeniera Informatika. Lalan'ny Mobility, Big Data, ary Fampidirana rafitra (MBDS)",license:"Diploma licence",education_second_box_title:"Oniversite Informatika",education_second_box_descirption:"Mari-pahaizana licence amin'ny Teknolojia Fampahalalam-baovao. Mifantoka tamin'ny fampandrosoana fampiharana na fandaharana rindrambaiko.",academic:"Akademika",education_third_box_title:"Fakulten'ny Siansa Matematika",education_third_box_description:"Famakafakana, Algebra, Hira, Vinavina sy Antontan'isa, Logika, Porofon-kevitra, ary Calculus Vector sy Matrix.",intensive_courses:"Fampianarana Intensive",languages:"Fiteny",malagasy:"Malagasy (MG)",french:"Frantsay (FR)",french_desc:"/ Fiteny faharoa",english:"Anglisy (EN)",english_desc:"Fahaizana matihanina",german:"Alemaina (DE)",german_desc:"Vaovao",my_works:"Asako",my_works_title:"Vahaolana mahafinaritra mahafeno ny andrasana: Tetikasa nataoko",my_works_introduction:"Mamolavola tranonkala miavaka mampifandray ny fiasa sy ny endrika, manome antoka ny fampiasana maharitra ho an'ny mpampiasa. Mamolavola interface tsara voalamina tsara sy tsara ara-drafitra, miantoka fifanakalozan-kevitra malefaka sy mora azo. Ny tanjona dia ny hamorona vahaolana mahafinaritra mifanaraka amin'ny filan'ny mpanjifa ankehitriny ary manomana azy ireo amin'ny ho avy.",load_more_work:"Te ahita tetikasa hafa",recommandation_title:"Manontany tena ny amin'izay lazain'ny mpiara-miasa amiko momba ahy? Ireto ny hevitr'izy ireo!",recommandation_introduction:"Satria mitady fahafahana matihanina vaovao aho, tiako ny hizara aminao ny fanamarihana avy amin'ny mpiara-miasa sy mpanolo-tsaina ahy. Ny valiny dia maneho ny fahaizako, ny etikan'ny asa ary ny fahaizako miasa amin'ny ekipa. Ny fanamarinana tsirairay dia manasongadina traikefa tokana, mampiseho ny toetra mampiavaka ahy ho kandidà tonga lafatra ho an'ny toeran'ny mpamorona rindrambaiko.",recommandation_conclusion:"Afaka manampy fanamarihana ao amin'ny LinkedIn ianao",contact_title:"Manana hevitra sa tetikasa ve ianao? Aza misalasala mamela hafatra!",contact_desc:"Raha mila fanampiana ianao, aza misalasala mifandray amiko ary ampahafantaro ahy ny fomba hanampiana anao. Fenoy ny taratasy (formulaire)  ary hamerina valiny aminao faran'izay haingana aho.",address:"Adiresy:",phone:"Telefaonina:",phone_form:"Telefaonina (Safidy)",name:"Anarana",ex_name:"oh: John Doe",ex_email:"oh: john.doe@gmail.com",optional:"Laharan-telefaonina",write_a_message:"Manorata Hafatra",send:"Alefaso",proundly:"Namorona tamin'ny fitiavana, Natao miaraka amin'ny fanavaozana",recommandation_name1:"Diary Razafinjatovo · 1.",recommandation_post1:"Lehiben'ny tetikasa / Certified Product Owner | Scrum Master",recommandation_date1:"Navoaka tamin'ny: 24 septambra 2024",recommandation_function1:"Diary no mpitantana mivantana an'i Danih Stephane",recommandation_desc1:"Nanana fahafinaretana niara-niasa tamin'i Danih aho amin'ny maha-mpitantana azy, ary afaka manamarina aho fa mpiasa tena miavaka izy. Manana fahalianana sy fitadiavana fanavaozana hatrany izy, ary mitondra vahaolana mamorona foana amin'ny tetikasa rehetra nandray anjara izy. \n Misongadina amin'ny fahamatorany, ny fandraisany andraikitra ary ny fahaizany maminavina ny filan'ny tetikasa izy raha mbola manolotra hevitra manavao. Na amin'ny famahana olana sarotra na amin'ny fanatsarana ny fizotran'ny fampandrosoana, dia mahita vahaolana mahomby hatrany izy. \n Ny hafanam-pony amin'ny fampandrosoana sy ny fitiavany ny antsipiriany dia mahatonga azy ho harena sarobidy ho an'ny ekipa rehetra. \n Manoro azy aho amin'ny fo rehetra.",recommandation_name2:"ZAFIMANANGA Josio Rigonolde · 1.",recommandation_post2:"Mpanamboatra PHP (Symfony, WordPress, ...) / ReactJs",recommandation_date2:"Navoaka tamin'ny: 23 septambra 2024",recommandation_function2:"ZAFIMANANGA niara-niasa tamin'i Danih Stephane tao amin'ny ekipa iray",recommandation_desc2:"Nahafinaritra ny niara-niasa akaiky tamin'i Danih izay naneho faharetana tamin'ny asa rehetra napetraka taminy. Na dia teo aza ny fanamby, dia nasehony hatrany ny fahavononana lehibe. \n Tao amin'ny ekipanay tao eTech, dia nanaraka haingana ny dingana sy ny fitaovana fampandrosoana napetraka izy. Ny fahaizany mifanaraka mora amin'ny tontolo miovaova dia toetra sarobidy izay mamela azy handray anjara amim-pahombiazana amin'ny tetikasa iombonana. \n Nandray ny toerany haingana tao anatin'ny ekipanay i Danih noho ny fanahiny tsara amin'ny fiaraha-miasa. Vonona hatrany hifanampy sy hizara ny heviny, dia nahatonga fiakarana tsara ho an'ny dinamikan'ny ekipa izy. \n Liana hatrany amin'ny fanatsarana ny fahaizany izy, izay mamela azy hivoatra haingana ary handray anjara lehibe amin'ny tetikasa tsirairay.",recommandation_name3:"Njaratiana Herivola RAZAFINDRABE · 1.",recommandation_post3:"Tech Lead (PHP/Symfony/Laravel) | Scrum Master | Product Owner",recommandation_date3:"Navoaka tamin'ny: 20 septambra 2024",recommandation_function3:"Njaratiana Herivola no mpitantana mivantana an'i Danih Stephane",recommandation_desc3:"Danih dia mpamorona manana hafanam-po, tena mihetsiketsika ary mihetsika mialoha. Miresaka tsara amin'ny ekipa izy ary koa amin'ny mpanjifanay. Izy koa dia mpanolo-tsaina tsara ho an'ireo mpianatra izay niasa tao amin'ny ekipa. Matetika izy no mampitolagaga anay amin'ny tetikasa fanampiny izay mampiseho ny fitiavany ny AI. Manoro azy tanteraka aho. Ho lasa mpitarika mpamorona tsara izy ;)",recommandation_name4:"Onintsoa Randriamiarinamanana · 1.",recommandation_post4:"Mpanamboatra IT",recommandation_date4:"Navoaka tamin'ny: 19 septambra 2024",recommandation_function4:"Onintsoa niara-niasa tamin'i Danih Stephane tao amin'ny ekipa iray",recommandation_desc4:"Nifandray tamin'i Danih tamin'ny tetikasa maro aho, ary tena miavaka ny fahaizany manamboatra programa. Madio sy voaomana tsara ny fehezam-potoana izay noforoniny. Mpanamboatra mahay izy, ary manoro azy aho tsy misy fisalasalana.",recommandation_name5:"Philibert Hemmy Ramananjato · 1.",recommandation_post5:"Injeniera amin'ny fampandrosoana rindrambaiko",recommandation_date5:"Navoaka tamin'ny: 19 septambra 2024",recommandation_function5:"Philibert Hemmy sy Danih Stephane dia niara-nianatra tany amin'ny sekoly iray",recommandation_desc5:"Izy dia mpiara-miasa tsara, izay miezaka hatrany hanatanteraka ny adidy sy vonona hanampy raha ilaina. Niasa tao anatin'ny ekipa iray matetika izahay. Izy dia mpanolo-tena tena matotra ary mandray ny andraikiny am-pahamalinana. Fatra-paharetana izy ary azo ianteherana hatrany. Manana fahaizana mampiala voly koa izy, izay tena ilaina indrindra rehefa tsy mandeha tsara araka ny efa nampoizina ny zavatra sasany.",recommandation_name6:"Masinavalona EMIR TOLOJANAHARY · 1.",recommandation_post6:"Mpanamboatra PHP/Javascript",recommandation_date6:"Navoaka tamin'ny: 1 oktobra 2024",recommandation_function6:"Masinavalona EMIR niara-niasa tamin'i Danih Stephane tao amin'ny ekipa iray",recommandation_desc6:"Niditra haingana tao anatin'ny ekipanay tao amin'ny tetikasa tao eTech i Danih, nanaraka mora ny fizotrany sy ny fitaovana nampiasaina. Mpitily hatrany izy, mampiseho fahaizana mifanampy lehibe mba hanaraka ny filan'ny ekipa. Tena mahatalanjona ny faharetany sy ny fahavononany, izay mahatonga azy ho mpiara-miasa azo itokisana sy tena sarobidy. \n Manana fanahy fiaraha-miasa tsara izy ary mitondra hery tsara izay manamafy ny dinamikan'ny ekipa. \n Ny iray amin'ireo hevitra vao haingana nentiny dia ny fahalianany amin'ny fivoaran'ny faharanitan-tsaina artifisialy sy ny fampidirany izany mora ao amin'ny asa andavanandro ataon'ny mpamorona, ka manatsara ny fahombiazantsika. \n Ny fahalianany sy ny faniriany hianatra dia mamela azy hivoatra haingana sy handray anjara lehibe amin'ny tetikasa tsirairay. \n Manoro azy aho amin'ny fo manontolo.",popup_image1title:"Teknolojia PHP 8",popup_image1:"PHP 8 dia ampiasaina ho an'ny fitantanana ny automatisation ny dingana ETL, indrindra amin'ny fanamorana ny fanangonana, ny fanovana ary ny fametrahana angon-drakitra. M thanks to its new features, such as the JIT compiler and named arguments, PHP 8 optimizes the handling of complex data and ensures efficient processing. Ny toetra voatokana sy ny fitantanana henjana ny lesoka dia miantoka ihany koa ny fahamarinan-toerana sy ny fahaiza-manao ny scripts ETL.",popup_image2title:"Teknolojia Laravel 8",popup_image2:"Laravel 8 dia ampiasaina ho toy ny fototra amin'ny fananganana sy ny fitantanana ny dingana ETL, manolotra tontolo iainana matanjaka sy tsara rafitra ho an'ny fanangonana, ny fanovana ary ny fametrahana angon-drakitra. M thanks to its advanced features such as scheduling jobs, queues for managing background tasks, and its powerful Eloquent ORM, Laravel facilitates the management of large volumes of data and ensures efficient and secure processing. Ny framework dia ahafahana manao intégration malama amin'ny rafitra fitehirizana samihafa sy ny angon-drakitra mifamatotra, sady manamora ny fampandrosoana haingana sy azo tantanana noho ny rafitra modular sy scalable.",popup_image3title:"Teknolojia Docker",popup_image3:"Docker dia ampiasaina ho an'ny fanamafisana ny dingana ETL rehetra, manome tontolo iainana voafetra sy mitovy ho an'ny fanangonana, ny fanovana ary ny fametrahana angon-drakitra. Ny singa tsirairay amin'ny rojo ETL (databases, scripts de traitement, fitehirizana) dia voarakitra ao anaty containers, miantoka ny portabilité sy ny reproducibility tonga lafatra eo amin'ny tontolo iainana fananganana, fitsapana ary famokarana. Docker dia manamora ihany koa ny fametrahana sy ny fitantanana ny fiankinan-doha, sady manatsara ny fampiasana loharano noho ny orchestration ny containers, manome antoka ny fanatanterahana malama sy scalable ny pipeline ETL.",popup_image4title:"Jenkins",popup_image4:"Jenkins dia ampiasaina ho an'ny fanamafisana ny fametrahana sy ny intégration continue (CI/CD) ao anatin'ny tetikasa ETL. M thanks to its configurable pipelines, Jenkins allows scheduling and executing tests, builds, and deployments, thus ensuring that the ETL processes are systematically tested and deployed in a controlled environment. Izany dia manome antoka ny famoahana tsy tapaka sy azo antoka ny endri-javatra, miaraka amin'ny fanehoan-kevitra haingana momba ny olana mety hitranga.",popup_image5title:"Bitbucket",popup_image5:"Bitbucket dia miasa ho toy ny sehatra Git ho an'ny fitantanana ny kinova sy ny fiaraha-miasa amin'ny kaody loharano ny tetikasa ETL. Ny fiasa toy ny pull requests sy ny Bitbucket CI pipelines dia ahafahan'ny ekipa manara-maso ny fanovana ny kaody sy manome antoka ny fampandrosoana azo antoka sy mangarahara. Bitbucket dia ahafahana mandray anjara amin'ny fitaovana hafa ao amin'ny ekosistema toy ny Jira sy Confluence, manamora ny fitantanana mahomby ny tetikasa.",popup_image6title:"Linux Debian",popup_image6:"Linux Debian dia ny rafitra fiasana voafidy ho an'ny fitantanana ny infrastrukturam-panjakana ny tetikasa ETL. Fantatra amin'ny fahamarinan-toerany, ny fiarovana ary ny fahaiza-miasa ambony amin'ny teknolojia open-source, Debian dia miantoka tontolo iainana azo antoka ho an'ny fanatanterahana ny containers Docker, manamora ny fitantanana ny dingana ETL, ary manara-maso ny angon-drakitra sy ny serivisy samihafa ilaina.",popup_image7title:"PHPUnit miaraka amin'ny Sail",popup_image7:"PHPUnit dia ampiasaina ho an'ny fanamarinana ny kalitaon'ny kaody ao anatin'ny tetikasa ETL. M thanks to Laravel Sail, which is a local development environment based on Docker, it is easy to set up and run unit tests consistently and in isolation. Izany dia miantoka fa ny singa tsirairay amin'ny ETL dia miasa araka ny nantenaina alohan'ny hametrahana azy amin'ny pipeline lehibe.",popup_image8title:"Atlassian (Fitantanana Tetikasa)",popup_image8:"Atlassian dia ampiasaina ho an'ny fitantanana ny tetikasa ETL, manamora ny fanaraha-maso ny asa, ny fampandrosoana, ny fe-potoana, sy ny tanjona. M thanks to its integration with tools like Jira and Confluence, Atlassian facilitates seamless collaboration between teams, ensuring that every step of the ETL process is well documented, monitored, and completed within the deadlines.",popup_image9title:"Jira",popup_image9:"Jira dia ampiasaina ho an'ny fanaraha-maso ny asa sy ny loza mitranga mifandraika amin'ny fampandrosoana ny pipeline ETL. Ny dingana tsirairay amin'ny dingana, manomboka amin'ny fanangonana hatrany amin'ny fanovana sy ny fametrahana, dia tantanan'ny Jira, ahafahana manara-maso ny asa sy mitantana tsara ny laharam-pahamehana. Ny workflows personnalisés dia manampy amin'ny fanatsarana ny dingana, miaraka amin'ny sprints ho an'ny fitantanana ny cycles de développement.",popup_image10title:"Confluence (Atlassian)",popup_image10:"Confluence dia ampiasaina ho an'ny fanoratana sy ny fiaraha-miasa momba ny tetikasa ETL. Ny ampahany tsirairay amin'ny dingana, manomboka amin'ny antsipirian'ny teknika ka hatramin'ny fanapahan-kevitra ara-drafitra, dia voarakitra ao Confluence, ahafahan'ny ekipa manara-maso sy manara-maso. Ity sehatra afovoany ity dia manamora ihany koa ny fizarana ny fahalalana sy ny fanombanana ny vaovao manan-danja.",popup_image11title:"Metodolojia ETL miaraka amin'ny Laravel",popup_image11:"Ny metodolojia ETL dia miankina amin'ny Laravel ho an'ny fitantanana ny dingana fanangonana, fanovana ary fametrahana. Laravel dia manamora ny fananganana pipelines ETL modular sy extensible, miaraka amin'ny fitantanana mora ny asa voalahatra sy ny queues ho an'ny fanodinana angon-drakitra ao anaty. Ny fiasa tafiditra, toy ny ORM Eloquent, dia manamora ny fanodinana sy ny fanovana ny angon-drakitra alohan'ny hametrahana azy ao anaty tahirin-kevitra afovoany.",popup_image12title:"Famintinana ankapobeny ny ETL",popup_image12:"Ny tetikasa ETL dia mamaritra ny automatisation ny fanangonana angon-drakitra avy amin'ny loharano samihafa (CSV, SQL), ny fanovana azy ireo amin'ny alalan'ny dingana sarotra (fanadiovana, fanatsarana, famoronana features), ary ny fametrahana azy ireo ao anaty tahirin-kevitra afovoany. Ny dingana ETL dia mikendry ny hanome ny angon-drakitra ho an'ny fanadihadiana sy ny famolavolana amin'ny fotoana tena izy, manome antoka fa ny fanapahan-kevitra dia mifototra amin'ny angon-drakitra azo antoka sy maharitra.",popup_image13title:"Dashboard graphique de gestion",popup_image13:"Misy tonton-tafo sary avy amin'ny tetikasa mifandray ampidirina mba hanomezana ny fijery momba ny hetsika sy ny antontan'isa, izay entin'ny ETL sy ny angon-drakitra misy. Amin'ity fitaovana ity, afaka manara-maso ny fifanakalozana tsirairay ireo mpampiasa, mijery ny fivezivezen'ny angon-drakitra (indrindra fa ny fanovana), mamantatra ny tsy fahatomombanana na ny vato misakana, ary mahazo fahitana avy hatrany momba ny angon-drakitra efa novaina.",popup_image14title:"Microservice miaraka amin'ny API",popup_image14:"Ireo tetikasa rehetra mifandraika amin'ny ETL dia natao ihany koa ho microservices, izay misaraka tsirairay ireo singa ao amin'ny pipeline ary mifandray amin'ny alàlan'ny API REST. Izany dia manome fahafaha-manaony, modularité, ary fitomboan'ny rafitra. Ny microservice tsirairay dia miandraikitra ny ampahany amin'ny dingana (fakana, fanovana na famoahana) ary azo apetraka sy havaozina tsy miankina, ary miaraka miasa tsy misy olana amin'ny singa hafa amin'ny alàlan'ny API voafaritry ny fenitra.",popup_image15title:"JavaScript ES6 (ECMAScript 6)",popup_image15:"Manatsara ny fitantanana ny lojika eo amin'ny mpanjifa ny JavaScript ES6 amin'ny alalan'ny fanolorana fiasa maoderina toy ny kilasy, modules, promises, ary fanamorana ny syntaxe. Ho an'ity tetikasa ity, manamora ny fanovàna ny DOM, ny fitantanana ny hetsika mpampiasa, ary ny fandefasana fangatahana asynchrone any amin'ny API ny ES6. Ireo fiasa ireo dia manatsara ny fahavitrihana sy ny fanehoan-kevitra amin'ny interface mpampiasa.",popup_image16title:"jQuery",popup_image16:"Manamora ny fifandraisana amin'ny DOM, ny fitantanana ny animation, ny fangatahana AJAX, ary ny fanovàna hetsika ny jQuery. Na dia manolotra safidy nativa aza ny ES6, dia mbola ilaina ny jQuery mba hiantohana ny fifanarahana amin'ny navigateur taloha sy hanamora ny asa sarotra sasany. Ao amin'ity tetikasa ity, azo ampiasaina ny jQuery mba hitantana ny singa mifandraika haingana sy mahomby.",popup_image17title:"Webpack",popup_image17:"Webpack dia module bundler izay manamora ny fitantanana ny fiankinan-doha sy ny fanangonana ny rakitra JavaScript, CSS, sary, ary loharano hafa ao amin'ny tetikasa. Ho an'ny fampiharana SaaS, azo ampiasaina ny Webpack mba hanatsara ny fahombiazana amin'ny fananganana rakitra bundles voaomana sy amin'ny fandefasana ny singa ilaina am-pilaminana, izay manatsara ny fotoana fidirana amin'ny fampiharana.",popup_image18title:"Metronic 8 Dashboard",popup_image18:"Metronic 8 dia tabilao fitantanana mifototra amin'ny Bootstrap, novolavolaina mba ho mora ampidirina amin'ny fampiharana web. Ao amin'ity tetikasa ity, manome fahafahana hamorona interface mpampiasa maoderina sy madio ho an'ny mpampiasa ny Metronic 8, miaraka amin'ny singa efa vonona ho an'ny sary, ny endrika, ary ny tabilao statistika.",popup_image19title:"PHP version 8",popup_image19:"Manolotra fanatsarana lehibe amin'ny lafiny fahombiazana ny PHP 8 noho ny mpanangona JIT (Just-In-Time) azy. Ao anatin'ny tetikasa, manamora ny fanatsarana ny asan'ny backend ny PHP 8 amin'ny fitantanana sy fanodinana ny angon-drakitra, indrindra fa amin'ny asa fikarohana sy fanadihadiana statistika. Ankoatra izany, ny fiasa vaovao toy ny Union Types, Named Arguments, ary Attributes dia manamora ny fanoratana kaody malefaka sy mora vakiana.",popup_image20title:"SSH Server",popup_image20:"SSH (Secure Shell) dia protokola izay mamela ny fitantanana ny lohamilina lavitra amin'ny fomba azo antoka. Ao amin'ity tetikasa ity, ampiasaina ny SSH amin'ny fametrahana, fitantanana, ary fikojakojana ny fampiharana ao amin'ny lohamilina, miantoka ny fiarovana ny fifandraisana sy ny fandefasana angon-drakitra mandritra ny fanavaozana na fanamafisana.",popup_image21title:"SCRUM",popup_image21:"SCRUM dia fomba fanao Agile ampiasaina amin'ny fitantanana tetikasa sarotra, indrindra amin'ny fivoaran'ny rindranasa. Ao amin'ny toe-javatra fanatsarana ny fampiharana SaaS, manampy amin'ny fandaminana sy fananganana ny asa amin'ny fizarana kely antsoina hoe sprints ny SCRUM, izay ahafahana manome haingana ny fiasa azo ampiasaina sy mahazo fanehoan-kevitra matetika avy amin'ny mpampiasa na ireo liana. Manampy amin'ny fiaraha-miasa eo amin'ny ekipa ny SCRUM, miantoka ny fanovana tsy tapaka ary manatsara ny kalitaon'ny vokatra farany.",popup_image22title:"Fikarakarana Backend miaraka amin'ny Laravel",popup_image22:"Laravel dia framework PHP ampiasaina amin'ny fikarakarana backend amin'ny tetikasa. Manolotra rafitra MVC izay manamora ny fampivoarana haingana ny fampiharana web matanjaka izy. Ho an'ity tetikasa ity, manampy amin'ny fananganana fangatahana API, ny fitantanana ny tahiry angon-drakitra, ary ny fametrahana rafitra fanamarinana ny Laravel, miaraka amin'ny fampidirana fiasa toy ny fampandrenesana, ny filaharana (queues), ary ny fitantanana ny mpampiasa.",popup_image23title:"Fiarovana Laravel",popup_image23:"Jetstream sy Breeze no safidy ho an'ny fanamarinana, miaraka amin'ny andraikitra sy fahazoan-dàlana voafaritra amin'ny alàlan'ny politika. Ny fiarovana CSRF dia mavitrika, ny angon-drakitra dia voamarina tsara, ary ny tenimiafina dia avoaka amin'ny bcrypt. Ny rakitra dia voatahiry am-pilaminana, ny angon-drakitra manan-danja dia voaaro, ary misy fiarovana amin'ny fanafihana XSS amin'ny alàlan'ny famotsorana ny angon-drakitra ao amin'ny sary. Misy tatitra momba ny asa ataon'ny mpampiasa, miaraka amin'ny famerana ny fikasana fidirana mba hisorohana ny fanafihana amin'ny alàlan'ny fanerena.",popup_image24title:"Fitantanana Laravel",popup_image24:"Ny kaody dia voalamina amina fomba modular ho an'ny rafitra mazava. Ny fifindra-monina dia ampiasaina ho an'ny angon-drakitra, ary ny mpandahateny mba hanamboarana asa ho azy. Ny fametrahana dia voafehy amin'ny rakitra .env, raha ny fametrahana dia mandeha ho azy amin'ny alàlan'ny pipelines CI/CD. PHPUnit dia ampiasaina ho an'ny fitsapana mandeha ho azy, ary ny cache toy ny Redis na Memcached dia manatsara ny fahombiazan'ny rafitra.",popup_image25title:"Fisehoan'ny Android amin'ny XML",popup_image25:"XML dia ampiasaina hamoronana ny interface utilisateur miaraka amin'ny layouts toy ny ConstraintLayout. Ny app dia manome antoka ny fidirana azo antoka miaraka amin'ny famaritana votoaty, amin'ny fanarahana ny fomba fanao tsara amin'ny fidirana. Ny fitoviana hita maso dia tazonina amin'ny alàlan'ny style sy lohahevitra XML, ary misy animation mba hampivoarana ny interface.",popup_image26title:"Rafitra Orchid (ERP Banky)",popup_image26:"Orchid dia ERP banky, izay ahafahana mitantana kaonty mpanjifa, fifanakalozana, trosa ary famatsiam-bola. Manana andraikitra amin'ny fitantanana ny risika sy ny fanarahana izy io. Ampiasaina ho backend ho an'ny app banky, manome API mba hanitsiana ny angon-drakitra amin'ny fotoana tena izy ary apetraka amin'ny lohamilina matanjaka miaraka amin'ny angon-drakitra tahiry toy ny Oracle na MySQL.",popup_image27title:"Fiteny JAVA ho an'ny Android",popup_image27:"Java dia fiteny fototra ho an'ny fampandrosoana Android, manatsara ny fandaharana mifantoka amin'ny zavatra sy ny fampifangaroana miaraka amin'ny Android SDK. Ny threads dia ampiasaina ho an'ny asa mavesatra, ary ny serivisy an-damosina dia miantoka ny fahamendrehan'ny fampiharana na dia eo aza ny fiatoana. Ny fitantanana ny zava-mitranga amin'ny alàlan'ny BroadcastReceiver dia manatsara ny traikefan'ny mpampiasa.",popup_image28title:"WSO2 API Manager",popup_image28:"WSO2 dia vahaolana open source amin'ny fitantanana API, miaro ny fidirana sy manara-maso ny fahombiazan'ny asa. Amin'ny fampiharana banky, dia miasa ho vavahady eo amin'ny front-end sy backend (ERP Orchid), amin'ny fitantanana ny fanamarinana amin'ny alàlan'ny OAuth2 na JWT. Izy io dia mamela ny famoahana sy ny fanavaozana ny API, miaraka amin'ny fitaovana fanaraha-maso mba hijerena ny fahombiazan'ny asa sy hiarovana ny tolotra banky.",popup_image29title:"Symfony — Backend Senior",popup_image29:"Symfony ampiasaina ho rafitra backend matanjaka amin'ny andraikitra Senior. Miantoka ny fahatanterahana ny API, ny fitantanana entité sarotra sy ny fampifangaroana amin'ny modiolin'ny sarintany sy AI.",popup_image30title:"WebSocket & Mercure — Fotoana Tena",popup_image30:"Ny WebSocket amin'ny alàlan'ny Mercure dia ampiasaina handefa angona sarintany amin'ny fotoana tena. Mamela fifandraisana roa-lela maharitra eo amin'ny mpizara sy ny mpanjifa tsy misy polling.",popup_image31title:"Symfony & REST API — Sehatra Fametahana",popup_image31:"Symfony miaraka amin'ny API Platform miasa ho backend RESTful voarindrina ho an'ny sehatra fametahana. Mitantana ny fahazoan'ny fiara, ny toetran'ny fametahana ary ny fampidirana ny fandoavana.",popup_image32title:"Symfony 7 — Fanofanana & Rafitra",popup_image32:"Symfony 7 ao amin'ny foibe ny tetikasa ampianarina, manome rafitra voalamina hampianarina ny rafitra maoderina, DDD sy ny foto-kevitr'ny CQRS.",popup_image33title:"Docker — Tontolo Azo Averina",popup_image33:"Docker ampiasaina hamoronana tontolo fampandrosoana azo averina, mahafeno ho an'ny fampidirana modely AI eo an-toerana (Ollama). Ny stack tsirairay dia containerisée ho an'ny fampiasana avy hatrany.",popup_image34title:"Next.js — SSR & App Router",popup_image34:"Next.js no framework React ampiasaina amin'ny andraikitra Senior. Mamela SSR, SSG ary App Router ho an'ny rafitra modular miaraka amin'ny fahombiazan'ny asa tsara.",popup_image35title:"React — Composants & State",popup_image35:"React ampiasaina hamoronana composant azo ampiasaina indray. Ny fitantanana ny state mandroso dia mitantana ny angon-drakitra sarintany sy ny fifandraisana sarotra.",popup_image36title:"TypeScript — Type Static",popup_image36:"TypeScript mitondra type static hentitra amin'ny codebase manontolo, mahita hadisoana amin'ny fotoana fanangonana ary miantoka ny fitantanana ny code sy ny interface matanjaka.",popup_image37title:"Claude AI — Fampidirana AI",popup_image37:"Ny Claude AI Anthropic dia ampidirina mba hampitombo ny modiolin'ny raharaha: famoronana famintinana, fanampy fanapahan-kevitra ary fanentanana asa sarotra amin'ny alàlan'ny Symfony.",popup_image38title:"Mercure — Push Fotoana Tena",popup_image38:"Ny protokola Mercure (mifototra amin'ny SSE) dia ampiasaina handefa amin'ny fotoana tena ny zava-mitranga sarintany sy ny fampandrenesana. Manalana ny polling tsy mahomby amin'ny alàlan'ny push server Symfony.",popup_image39title:"Next.js — Interface Fametahana",popup_image39:"Next.js manamboatra ny interface fametahana miaraka amin'ny App Router, navigation malefaka ary SSR/CSR hybrid rendering ho an'ny fampiana haingana.",popup_image40title:"React — UX Manetsika",popup_image40:"React mitantana ny filtrage dinamika ny fiara, fisehoana amin'ny fotoana tena ny fisian'ny fiara ary ny fitantanana ny dingana fametahana.",popup_image41title:"REST API — API Platform",popup_image41:"API Platform (amin'ny Symfony) mamorona amin'ny ho azy ny endpoint RESTful voarakitra. Mitantana ny loharanon'ny fiara, fametahana ary fandoavana miaraka amin'ny fiarovana JWT.",popup_image42title:"SEO — Fahitana & Fahombiazan'ny Asa",popup_image42:"Ny SEO dia amboarina amin'ny alàlan'ny Next.js: metadata dinamika, sitemap amin'ny ho azy, SSR ho an'ny Google indexing ary fanamboarana Core Web Vitals.",popup_image43title:"React — Tetikasa Nofaizina",popup_image43:"React no teknolojia fototra ampianarina amin'ny fanofanana. Ny mpandray anjara amin'ny karama ambany dia mianatra composant, hooks ary pattern matihanina amin'ny tetikasa tena izy.",popup_image44title:"Tailwind CSS — Design Utilitaire",popup_image44:"Tailwind CSS ampiasaina hamoronana interface maoderina haingana amin'ny alàlan'ny kilasy utility. Ampianarina ho solon'ny Bootstrap miaraka amin'ny fanaraha-maso design.",popup_image45title:"Mercure — Fotoana Tena amin'ny Fanofanana",popup_image45:"Ny protokola Mercure dia ampidirina amin'ny tetikasa nofaizina mba hampianatra ny ekipa ny foto-kevitry ny fotoana tena ary ny server push amin'ny Symfony.",popup_image46title:"Claude AI — Vahaolana AI eo An-toerana",popup_image46:"Vahaolana AI eo an-toerana mifototra amin'ny Ollama (LLaMA, Mistral) sy ny API Claude dia ampidirina amin'ny tetikasa, manampy ny famoronana code sy fanampiana teknika.",popup_image47title:"shadcn/ui — Composants UI Maoderina",popup_image47:"shadcn/ui ampiasaina amin'ny andraikitra Senior hanamboarana interface matihanina haingana miaraka amin'ny composants azo ovana sy tsy bundlés, mifanentana amin'ny Next.js, Tailwind CSS ary TypeScript.",popup_image48title:"PMO — Fitantanana Tetikasa",popup_image48:"Amin'ny maha PMO, nitantana ny dingana feno ny tetikasa aho: drafitry ny asa, fanaraha-maso roadmap, fitantanana ny hasasarana ary fandefasana amin'ny famokarana. Nisolo tena ny mpandraharaha teknika sy ny fitantanana.",popup_image49title:"shadcn/ui — Interface Fametahana",popup_image49:"shadcn/ui nampiasaina hanamboarana haingana ny interface fametahana: forms dingana maro, modals, fipiliana daty ary dashboards, mifanentana amin'ny Next.js sy Tailwind.",popup_image50title:"Leaflet — Sarintany Mifanerasera",popup_image50:"Leaflet (React-Leaflet) no injiny sarintany amin'ny AGREETECH. Mampiseho ny faritra fambolena ary mampifandray Leaflet Draw ho an'ny famoronana tanana polygon sy marque amin'ny sarintany.",popup_image51title:"Google Earth Engine — Sary Satalaita",popup_image51:"Google Earth Engine ampiasaina amin'ny famakafakana sary satalaita: NDVI, fampiasana ny tany, fanovana ny toetrandro ary famotopotorana ny tontolo iainana amin'ny faritra nosaritana.",popup_image52title:"Turf.js — Kajy Jeospasialy",popup_image52:"Turf.js manatanteraka kajy jeospasialy amin'ny client: velarana, sisiny, centroïde, fanamarinanana GeoJSON, fifanentanana sy buffer — tsy mila antso server.",popup_image53title:"React 19 — Interface Agentique",popup_image53:"React 19 manamboatra ny interface AGREETECH miaraka amin'ny composants sarintany, famakafakana ary fisehoana modular sy mivantana.",popup_image54title:"TypeScript 5.8 — Type Jeometria",popup_image54:"TypeScript 5.8 manampy type amin'ny rafitra GeoJSON, Redux ary REST API, miaro amin'ny hadisoana coordinates ary miantoka ny fahamendrehan'ny angona jeografy.",popup_image55title:"Redux Toolkit — State Fampiharana",popup_image55:"Redux Toolkit mitantana ny state global: faritra nosaritana, vokatra famakafakana, state sarintany ary filters miaraka amin'ny slices voalamina.",popup_image56title:"React Query — Angona Server",popup_image56:"TanStack React Query mampifandray ny frontend sy REST API miaraka amin'ny cache maranitra, re-fetching amin'ny ho azy ary fitantanana ny state fampiana/hadisoana.",popup_image57title:"Material-UI — Design System",popup_image57:"MUI v7 miaraka amin'ny Emotion manome ny design system feno: panels famakafakana, forms, drawers sarintany ary dashboards miaraka amin'ny theme manokana.",popup_image58title:"Vite — Build Haingana",popup_image58:"Vite 7 manome fandehanana haingana ny server dev sy build famokarana optimisé miaraka amin'ny HMR haingana ho an'ny composants sarintany sarotra.",popup_image59title:"Chart.js — Fisehoana Tontolo Iainana",popup_image59:"Chart.js (react-chartjs-2) mampiseho angon-drakitra tontolo iainana: grafika NDVI, histograma fampiasana tany ary setriny ara-toetrandro, mifandray amin'ny faritra voafantina amin'ny sarintany.",authentification_securisee:"Fanamarinana voaaro",integration_paiement:"Fampidirana fandoavam-bola",cms_sur_mesure:"CMS araka ny filàna",optimisation_bdd:"Fanatsarana BDD",frontend:"Frontend",interfaces_modernes_reactives:"Interface maoderina sy mivantana",applications_spa:"Fampiharana SPA",ui_ux_responsive:"UI/UX mivadika",animations_fluides:"Fampisehoana malefaka",dashboards_interactifs:"Dashboard mifandray",performance_optimisee:"Fahaizana voaomana",specialises:"Manam-pahaizana",solutions_techniques_sur_mesure:"Vahaolana teknika araka ny filàna",ecommerce_avance:"E-commerce mandroso",systemes_de_reservation:"Rafitra famandrihana",applications_metier:"Fampiharana asa",automatisation:"Automatisation",seo_technique:"SEO teknika",maintenance:"Fikarakarana",support_optimisation_continue:"Fanohanana sy fanatsarana mitohy",maintenance_preventive:"Fikarakarana mialoha",securite_renforcee:"Fiarovana matanjaka",performance_optimale:"Fahaizana tsara indrindra",support_reactif:"Fanohanana mivantana",monitoring_24_7:"Fanaraha-maso 24/7",conseil:"Torohevitra",expertise_technique_strategique:"Fahaizana teknika sy stratejika",audit_approfondi:"Fanadihadiana lalina",architecture_systeme:"Rafitra sy rafitra",securite_avancee:"Fiarovana mandroso",analyse_strategique:"Fanadihadiana stratejika",formation_equipe:"Fampiofanana ekipa",autres_services:"Services hafa",services_devops:"Services DevOps",services_tests_qualite:"Services fanandramana sy kalitao",services_r_d_technologique:"Services R&D teknolojika",accompagnement_croissance_digitale:"Fanohanana amin'ny fitomboana dizitaly",what_i_offer:"Izay atolotro",mes_services:"Ny Serivisy",solutions_cloud:"Vahaolana Cloud",backend:"Backend",architecture_robuste_apis_performantes:"Rafitra matanjaka sy APIs mahomby",apis_restful:"APIs RESTful","publish-date1":"15 Novambra 2021","publish-date2":"11 Avrily 2022","publish-date3":"23 Mey 2022","publish-date4":"8 Mey 2023","publish-date5":"21 Jiona 2023","publish-date6":"14 Aogositra 2023","publish-date7":"30 Jiona 2024"}};function applyTranslations(e){document.querySelectorAll("[data-translate]").forEach(a=>{const n=a.getAttribute("data-translate");translations[e]&&translations[e][n]&&(void 0!==a.placeholder?a.placeholder=translations[e][n]:a.innerText=translations[e][n])})}let currentLanguage="fr";function changeLanguage(e){applyTranslations(e),changeFlag(e),changeLanguageTyped(e),currentLanguage=e,resetTypedAnimations(),changePopupLogo(),changeSwithSkills(),changeGameLang()}function changePopupLogo(){const e=document.querySelector(".animated-text"),a=e.classList;for(let e=a.length-1;e>=0;e--)a[e].startsWith("option")&&a.remove(a[e]);e.classList.add("option"+currentLanguage)}function changeSwithSkills(){const e={fr:{value1:"165px",value2:"170px",value3:"155px"},en:{value1:"93px",value2:"98px",value3:"94px"},de:{value1:"145px",value2:"150px",value3:"145px"},mg:{value1:"178px",value2:"185px",value3:"138px"}};!function(){if(e[currentLanguage]){const a=e[currentLanguage];Object.entries(a).forEach(([e,a])=>{document.documentElement.style.setProperty(`--width-${e}`,a)})}}()}function changeFlag(e){const a={fr:{src:"./assets/img/Flag_of_France.svg",code:"FR"},en:{src:"./assets/img/Flag_of_the_United_States.svg",code:"EN"},mg:{src:"./assets/img/Flag_of_Madagascar.svg",code:"MG"},de:{src:"./assets/img/Flag_of_Germany.svg",code:"DE"}}[e];if(!a)return;const n=document.getElementById("lang-flag"),i=document.getElementById("lang-code");n&&(n.src=a.src),i&&(i.textContent=a.code),document.querySelectorAll(".lang-option").forEach(a=>{a.classList.toggle("active",a.dataset.lang===e)})}const translationsTyped={fr:["Ingénieur","Développeur","Codeur"],en:["Engineer","Developer","Coder"],de:["Ingenieur","Entwickler","Programmierer"],mg:["Injeniera","Mpamorona rindrambaiko","Mpikirakira kaody"]};let typed;function changeLanguageTyped(e){typed&&typed.forEach(e=>e.destroy());const a=document.querySelectorAll(".auto-type");typed=[],a.forEach(a=>{const n=new Typed(a,{strings:translationsTyped[e],typeSpeed:150,backSpeed:150,loop:!0});typed.push(n)})}const translationsEducation={en:{autoType4:["Experience"],autoType5:["I have had the opportunity to work on various projects, primarily in the field of SaaS solutions and cloud services. During these experiences, I have been involved in several tasks and responsibilities, ranging from developing specific features to optimizing system architecture. This immersion has allowed me to gain a solid understanding of the technical challenges and best practices associated with these dynamic environments."],autoType6:["Education"],autoType7:["During my educational journey in computer development, I had the opportunity to earn a master's degree from one of the best universities in Europe, where I deepened my theoretical and practical knowledge. This experience allowed me to strengthen my application development skills while benefiting from a solid computer science education provided by local universities. At the same time, I acquired a rigorous foundation in mathematics, essential for solving complex problems and optimizing algorithms, thus preparing me to tackle the technical challenges of the industry."]},fr:{autoType4:["Expérience"],autoType5:["J’ai eu l’opportunité de travailler sur divers projets, principalement dans le domaine des solutions SaaS et des services cloud. Au cours de ces expériences, j'ai été impliqué dans plusieurs tâches et responsabilités, allant du développement de fonctionnalités spécifiques à l'optimisation de l'architecture des systèmes. Cette immersion m'a permis d'acquérir une solide compréhension des défis techniques et des meilleures pratiques associés à ces environnements dynamiques."],autoType6:["Éducation"],autoType7:["Au cours de mon parcours scolaire en développement informatique, j'ai eu l'opportunité d'obtenir une maîtrise dans l'une des meilleures universités d'Europe, où j'ai approfondi mes connaissances théoriques et pratiques. Cette expérience m'a permis de renforcer mes compétences en développement d'applications, tout en bénéficiant d'une solide formation en informatique dispensée par des universités locales. Parallèlement, j'ai acquis une base rigoureuse en mathématiques, essentielle pour la résolution de problèmes complexes et l'optimisation des algorithmes, me préparant ainsi à relever les défis techniques du secteur."]},de:{autoType4:["Erfahrung"],autoType5:["Ich hatte die Gelegenheit, an verschiedenen Projekten zu arbeiten, hauptsächlich im Bereich SaaS-Lösungen und Cloud-Dienste. Während dieser Erfahrungen war ich an mehreren Aufgaben und Verantwortlichkeiten beteiligt, von der Entwicklung spezifischer Funktionen bis hin zur Optimierung der Systemarchitektur. Diese Eintauchen ermöglichte es mir, ein solides Verständnis der technischen Herausforderungen und bewährten Verfahren in diesen dynamischen Umgebungen zu erlangen."],autoType6:["Ausbildung"],autoType7:["Während meiner Ausbildung in der Computerentwicklung hatte ich die Möglichkeit, einen Master-Abschluss an einer der besten Universitäten Europas zu erwerben, wo ich mein theoretisches und praktisches Wissen vertiefte. Diese Erfahrung ermöglichte es mir, meine Fähigkeiten in der Anwendungsentwicklung zu stärken, während ich von einer soliden Informatikausbildung profitierte, die von lokalen Universitäten angeboten wurde. Gleichzeitig erwarb ich eine strenge Grundlage in Mathematik, die wesentlich ist, um komplexe Probleme zu lösen und Algorithmen zu optimieren, und die mich darauf vorbereitete, die technischen Herausforderungen der Branche zu bewältigen."]},mg:{autoType4:["Traikefa"],autoType5:["Nanana fahafahana niasa tamin'ny tetikasa maro aho, indrindra fa teo amin'ny sehatry ny vahaolana SaaS sy ny tolotra rahona. Tamin'ireo traikefa ireo dia nandray anjara tamin'ny asa sy andraikitra maro aho, manomboka amin'ny fampivoarana ny endri-javatra manokana ka hatramin'ny fanatsarana ny rafitra. Ity fampidirana ity dia nanome ahy fahatakarana matanjaka momba ny fanamby ara-teknika sy ny fomba fanao tsara indrindra mifandraika amin'ireo tontolo mavitrika ireo."],autoType6:["Fampianarana"],autoType7:["Nandritra ny làlan'ny fianarako momba ny fampandrosoana informatika, dia nanana fahafahana nahazo mari-pahaizana Master avy amin'ny iray amin'ireo oniversite tsara indrindra any Eoropa aho, izay nampitomboako ny fahalalako ara-teorika sy azo ampiharina. Ity traikefa ity dia nanampy ahy hanatsara ny fahaizako amin'ny fampandrosoana fampiharana, sady nahazo tombony avy amin'ny fampianarana informatika matanjaka nomen'ny oniversite eto an-toerana. Mandritra izany fotoana izany dia nahazo fanabeazana hentitra amin'ny matematika aho, izay ilaina amin'ny famahana olana sarotra sy fanatsarana algorithma, ka nanomana ahy hiatrika ireo fanamby ara-teknika eo amin'ny sehatry ny indostria."]}},typedInstances={},fastTypedRAFs={};function startTyped(e,a,n){typedInstances[e]&&(typedInstances[e].destroy(),delete typedInstances[e]);const i=document.querySelector(e);i&&(i.textContent=""),typedInstances[e]=new Typed(e,{strings:a,typeSpeed:n,backSpeed:n,loop:!1,showCursor:!1})}function startFastTyped(e,a,n){fastTypedRAFs[e]&&(cancelAnimationFrame(fastTypedRAFs[e]),delete fastTypedRAFs[e]);const i=document.querySelector(e);if(!i)return;const t=a[0]||"";i.textContent="";let r=0;fastTypedRAFs[e]=requestAnimationFrame(function a(){r<t.length?(r=Math.min(r+n,t.length),i.textContent=t.slice(0,r),fastTypedRAFs[e]=requestAnimationFrame(a)):delete fastTypedRAFs[e]})}function startAnimationForTarget(e){e.classList.contains("auto-type4")?startTyped(".auto-type4",translationsEducation[currentLanguage].autoType4,150):e.classList.contains("auto-type5")?startFastTyped(".auto-type5",translationsEducation[currentLanguage].autoType5,30):e.classList.contains("auto-type6")?startTyped(".auto-type6",translationsEducation[currentLanguage].autoType6,150):e.classList.contains("auto-type7")&&startFastTyped(".auto-type7",translationsEducation[currentLanguage].autoType7,30)}let options={root:null,rootMargin:"0px",threshold:.3},observer=new IntersectionObserver(function(e){e.forEach(e=>{e.isIntersecting&&startAnimationForTarget(e.target)})},options),targets=document.querySelectorAll(".auto-type4, .auto-type5, .auto-type6, .auto-type7");targets.forEach(e=>{observer.observe(e)}),window.onload=function(){applyTranslations("fr"),changeFlag("fr"),changeLanguageTyped("fr"),resetTypedAnimations(),particleSystem.init(),particleSystem.animate();const e=document.querySelector(".theme-btn");e.classList.contains("active")||e.click();const a=document.getElementById("lang-switcher"),n=document.getElementById("lang-btn");n.addEventListener("click",()=>{const e=a.classList.toggle("open");n.setAttribute("aria-expanded",e)}),document.querySelectorAll(".lang-option").forEach(e=>{e.addEventListener("click",()=>{changeLanguage(e.dataset.lang),a.classList.remove("open"),n.setAttribute("aria-expanded","false")})}),document.addEventListener("click",e=>{e.isTrusted&&!a.contains(e.target)&&(a.classList.remove("open"),n.setAttribute("aria-expanded","false"))})};